CREATE OR REPLACE FUNCTION public.moreai_admin_mutate_llm_route(p_actor_user_id uuid, p_policy_id uuid, p_task_type text, p_model_id uuid, p_fallback_model_id uuid, p_priority integer, p_enabled boolean, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_policy public.llm_routing_policies%rowtype;
  v_action text;
begin
  if p_actor_user_id is null
    or p_task_type not in ('general', 'chat', 'planning')
    or p_model_id is null
    or p_priority < 0 then
    raise exception using errcode='22023', message='LLM_ROUTE_INVALID';
  end if;

  if not exists (
    select 1 from public.user_role_assignments ura
    join public.roles r on r.id=ura.role_id
    join public.role_permissions rp on rp.role_id=r.id
    join public.permissions p on p.id=rp.permission_id
    where ura.user_id=p_actor_user_id and ura.scope_type='platform'
      and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now())
      and r.scope='platform' and p.key='platform.models.manage'
  ) then
    raise exception using errcode='42501', message='ADMIN_PERMISSION_DENIED';
  end if;

  if p_enabled and not exists (
    select 1 from public.llm_models m
    join public.llm_providers pr on pr.id=m.provider_id
    where m.id=p_model_id and m.enabled=true and pr.enabled=true
  ) then
    raise exception using errcode='55000', message='LLM_PRIMARY_MODEL_NOT_READY';
  end if;

  if p_enabled and p_fallback_model_id is not null and not exists (
    select 1 from public.llm_models m
    join public.llm_providers pr on pr.id=m.provider_id
    where m.id=p_fallback_model_id and m.enabled=true and pr.enabled=true
  ) then
    raise exception using errcode='55000', message='LLM_FALLBACK_MODEL_NOT_READY';
  end if;

  if p_policy_id is null then
    insert into public.llm_routing_policies(
      scope_type,scope_id,task_type,model_id,priority,fallback_model_id,enabled
    ) values ('platform',null,p_task_type,p_model_id,p_priority,p_fallback_model_id,p_enabled)
    returning * into v_policy;
    v_action := 'llm.routing.create';
  else
    select * into v_policy from public.llm_routing_policies
    where id=p_policy_id and scope_type='platform' and scope_id is null for update;
    if not found then
      raise exception using errcode='P0002', message='LLM_ROUTE_NOT_FOUND';
    end if;
    update public.llm_routing_policies
    set task_type=p_task_type,model_id=p_model_id,priority=p_priority,
        fallback_model_id=p_fallback_model_id,enabled=p_enabled
    where id=p_policy_id returning * into v_policy;
    v_action := 'llm.routing.update';
  end if;

  insert into public.admin_audit_logs(
    actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata
  ) values (
    p_actor_user_id,v_action,'llm_routing_policy',v_policy.id::text,'platform',
    coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text),'success',
    jsonb_build_object('task_type',v_policy.task_type,'model_id',v_policy.model_id,
      'fallback_model_id',v_policy.fallback_model_id,'priority',v_policy.priority,'enabled',v_policy.enabled)
  );

  return jsonb_build_object('id',v_policy.id,'task_type',v_policy.task_type,
    'model_id',v_policy.model_id,'fallback_model_id',v_policy.fallback_model_id,
    'priority',v_policy.priority,'enabled',v_policy.enabled);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_admin_assign_platform_role(p_actor_user_id uuid, p_target_user_id uuid, p_role_key text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_role public.roles%rowtype; v_assignment public.user_role_assignments%rowtype; v_correlation text:=coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text);
begin
 if p_actor_user_id is null or p_target_user_id is null or p_role_key is null then raise exception using errcode='22023',message='ROLE_ASSIGNMENT_INVALID'; end if;
 if not exists(select 1 from public.user_role_assignments ura join public.roles r on r.id=ura.role_id join public.role_permissions rp on rp.role_id=r.id join public.permissions p on p.id=rp.permission_id
  where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform' and r.key='super_admin' and p.key='platform.roles.assign') then
  raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED'; end if;
 if p_expires_at is not null and p_expires_at<=now() then raise exception using errcode='22023',message='ROLE_EXPIRY_MUST_BE_FUTURE'; end if;
 select * into v_role from public.roles where key=p_role_key and scope='platform';
 if not found then raise exception using errcode='P0002',message='PLATFORM_ROLE_NOT_FOUND'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_target_user_id::text||':'||v_role.id::text,0));
 select * into v_assignment from public.user_role_assignments where user_id=p_target_user_id and role_id=v_role.id and scope_type='platform' and scope_id is null
  order by created_at desc limit 1 for update;
 if found then
  if v_assignment.expires_at is null or v_assignment.expires_at>now() then return jsonb_build_object('assignment',to_jsonb(v_assignment),'role_key',v_role.key,'replayed',true); end if;
  update public.user_role_assignments set assigned_by=p_actor_user_id,expires_at=p_expires_at where id=v_assignment.id returning * into v_assignment;
 else
  insert into public.user_role_assignments(user_id,role_id,scope_type,scope_id,assigned_by,expires_at) values(p_target_user_id,v_role.id,'platform',null,p_actor_user_id,p_expires_at) returning * into v_assignment;
 end if;
 insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
 values(p_actor_user_id,'rbac.role.assign','user_role_assignment',v_assignment.id::text,'platform',v_correlation,'success',jsonb_build_object('target_user_id',p_target_user_id,'role_key',v_role.key,'expires_at',v_assignment.expires_at));
 return jsonb_build_object('assignment',to_jsonb(v_assignment),'role_key',v_role.key,'replayed',false);
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_workspace_claim_chat_idempotency(p_scope_key text, p_idempotency_key text, p_request_hash text, p_expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.idempotency_keys%rowtype;
begin
 if coalesce(p_scope_key,'')='' or coalesce(p_idempotency_key,'')='' or length(p_idempotency_key)>200
  or coalesce(p_request_hash,'')='' or p_expires_at<=now() then
  raise exception using errcode='22023',message='CHAT_IDEMPOTENCY_INVALID';
 end if;
 insert into public.idempotency_keys(scope_key,idempotency_key,request_hash,status,expires_at)
 values(p_scope_key,p_idempotency_key,p_request_hash,'processing',p_expires_at)
 on conflict(scope_key,idempotency_key) do update
  set request_hash=excluded.request_hash,status='processing',response_status=null,response_body=null,
      expires_at=excluded.expires_at,updated_at=now()
  where public.idempotency_keys.expires_at<=now() or public.idempotency_keys.status='failed'
 returning * into v_row;
 if found then return jsonb_build_object('state','claimed'); end if;
 select * into v_row from public.idempotency_keys
  where scope_key=p_scope_key and idempotency_key=p_idempotency_key for update;
 if not found then raise exception using errcode='40001',message='CHAT_IDEMPOTENCY_RETRY'; end if;
 if v_row.request_hash<>p_request_hash then return jsonb_build_object('state','conflict'); end if;
 if v_row.status='completed' then
  return jsonb_build_object('state','completed','response_status',v_row.response_status,'response_body',v_row.response_body);
 end if;
 return jsonb_build_object('state','processing');
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_admin_set_role_permission(p_actor_user_id uuid, p_role_key text, p_permission_key text, p_enabled boolean, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_role public.roles%rowtype; v_permission public.permissions%rowtype; v_correlation text:=coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text);
begin
 if p_actor_user_id is null or coalesce(p_role_key,'')='' or coalesce(p_permission_key,'')='' or p_enabled is null then
  raise exception using errcode='22023',message='ROLE_PERMISSION_INVALID';
 end if;
 if not exists(
  select 1 from public.user_role_assignments ura
  join public.roles r on r.id=ura.role_id
  join public.role_permissions rp on rp.role_id=r.id
  join public.permissions p on p.id=rp.permission_id
  where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null
   and (ura.expires_at is null or ura.expires_at>now())
   and r.scope='platform' and r.key='super_admin'
   and p.key in ('platform.roles.assign','platform.security.manage')
  group by ura.id having count(distinct p.key)=2
 ) then raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED'; end if;
 select * into v_role from public.roles where key=p_role_key and scope='platform' for update;
 if not found then raise exception using errcode='P0002',message='PLATFORM_ROLE_NOT_FOUND'; end if;
 if v_role.key='super_admin' then raise exception using errcode='55000',message='SUPER_ADMIN_PERMISSION_MATRIX_IMMUTABLE'; end if;
 if p_enabled and p_permission_key in ('platform.roles.assign','platform.security.manage') then
  raise exception using errcode='42501',message='PRIVILEGED_PERMISSION_CANNOT_BE_DELEGATED';
 end if;
 select * into v_permission from public.permissions where key=p_permission_key;
 if not found then raise exception using errcode='P0002',message='PERMISSION_NOT_FOUND'; end if;
 if p_enabled then
  insert into public.role_permissions(role_id,permission_id) values(v_role.id,v_permission.id)
  on conflict(role_id,permission_id) do nothing;
 else
  delete from public.role_permissions where role_id=v_role.id and permission_id=v_permission.id;
 end if;
 insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
 values(p_actor_user_id,case when p_enabled then 'rbac.permission.grant' else 'rbac.permission.revoke' end,
  'role_permission',v_role.id::text,'platform',v_correlation,'success',
  jsonb_build_object('role_key',v_role.key,'permission_key',v_permission.key,'enabled',p_enabled));
 return jsonb_build_object('role_key',v_role.key,'permission_key',v_permission.key,'enabled',p_enabled);
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_admin_mutate_llm_provider(p_actor_user_id uuid, p_provider_id uuid, p_key text, p_display_name text, p_enabled boolean, p_credentials_ready boolean, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_provider public.llm_providers%rowtype; v_action text;
begin
 if p_actor_user_id is null or p_key not in ('google','openai','anthropic') or length(trim(coalesce(p_display_name,'')))<2 or length(trim(coalesce(p_display_name,'')))>120 then
  raise exception using errcode='22023',message='LLM_PROVIDER_INVALID';
 end if;
 if not exists(select 1 from public.user_role_assignments ura join public.roles r on r.id=ura.role_id join public.role_permissions rp on rp.role_id=r.id join public.permissions p on p.id=rp.permission_id
  where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform' and p.key='platform.models.manage') then
  raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED';
 end if;
 if p_enabled and not coalesce(p_credentials_ready,false) then raise exception using errcode='55000',message='PROVIDER_CREDENTIALS_NOT_CONFIGURED'; end if;
 if p_provider_id is null then
  insert into public.llm_providers(key,display_name,enabled,config) values(p_key,trim(p_display_name),p_enabled,'{}'::jsonb) returning * into v_provider;
  v_action:='llm.provider.create';
 else
  select * into v_provider from public.llm_providers where id=p_provider_id for update;
  if not found then raise exception using errcode='P0002',message='LLM_PROVIDER_NOT_FOUND'; end if;
  if v_provider.key<>p_key then raise exception using errcode='22023',message='LLM_PROVIDER_KEY_IMMUTABLE'; end if;
  update public.llm_providers set display_name=trim(p_display_name),enabled=p_enabled,updated_at=now() where id=p_provider_id returning * into v_provider;
  v_action:='llm.provider.update';
 end if;
 insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
 values(p_actor_user_id,v_action,'llm_provider',v_provider.id::text,'platform',coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text),'success',
  jsonb_build_object('key',v_provider.key,'display_name',v_provider.display_name,'enabled',v_provider.enabled,'credentials_ready',coalesce(p_credentials_ready,false)));
 return jsonb_build_object('id',v_provider.id,'key',v_provider.key,'display_name',v_provider.display_name,'enabled',v_provider.enabled);
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_admin_revoke_platform_role(p_actor_user_id uuid, p_assignment_id uuid, p_reason text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_assignment public.user_role_assignments%rowtype; v_role public.roles%rowtype; v_super_admin_count integer; v_correlation text:=coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text);
begin
 if p_actor_user_id is null or p_assignment_id is null or length(coalesce(p_reason,''))>500 then raise exception using errcode='22023',message='ROLE_REVOCATION_INVALID'; end if;
 if not exists(select 1 from public.user_role_assignments ura join public.roles r on r.id=ura.role_id join public.role_permissions rp on rp.role_id=r.id join public.permissions p on p.id=rp.permission_id
  where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform' and r.key='super_admin' and p.key='platform.roles.assign') then
  raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED'; end if;
 select * into v_assignment from public.user_role_assignments where id=p_assignment_id and scope_type='platform' and scope_id is null for update;
 if not found then raise exception using errcode='P0002',message='ROLE_ASSIGNMENT_NOT_FOUND'; end if;
 select * into v_role from public.roles where id=v_assignment.role_id;
 if v_role.key='super_admin' and (v_assignment.expires_at is null or v_assignment.expires_at>now()) then
  perform pg_advisory_xact_lock(hashtextextended('moreai:super_admin_revocation',0));
  select count(*) into v_super_admin_count from public.user_role_assignments ura join public.roles r on r.id=ura.role_id
   where r.key='super_admin' and ura.scope_type='platform' and ura.scope_id is null and (ura.expires_at is null or ura.expires_at>now());
  if v_super_admin_count<=1 then raise exception using errcode='55000',message='LAST_SUPER_ADMIN_CANNOT_BE_REVOKED'; end if;
 end if;
 delete from public.user_role_assignments where id=p_assignment_id;
 insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
 values(p_actor_user_id,'rbac.role.revoke','user_role_assignment',p_assignment_id::text,'platform',v_correlation,'success',jsonb_build_object('target_user_id',v_assignment.user_id,'role_key',v_role.key,'reason',p_reason));
 return jsonb_build_object('assignment_id',p_assignment_id,'revoked',true);
end; $function$

CREATE OR REPLACE FUNCTION storage.delete_lifecycle_objects(object_ids uuid[])
 RETURNS TABLE(id uuid, is_delete_marker boolean, metadata jsonb)
 LANGUAGE plpgsql
AS $function$
DECLARE
    object_id uuid;
    deleted_row storage.objects%ROWTYPE;
    deleted_ids uuid[];
    deleted_markers boolean[];
    deleted_metadata jsonb[];
    bulk_deleted boolean := false;
BEGIN
    -- Surface pre-existing deferred violations instead of treating them as blocked rows.
    SET CONSTRAINTS ALL IMMEDIATE;
    PERFORM set_config('storage.allow_delete_query', 'true', true);

    -- One subxact keeps the subxid cache from overflowing; rows return only once it commits.
    BEGIN
        WITH deleted AS (
            DELETE FROM storage.objects AS object_row
              WHERE object_row.id = ANY(object_ids) AND object_row.archived_at IS NOT NULL
              RETURNING object_row.id, object_row.is_delete_marker, object_row.metadata
        )
        SELECT array_agg(deleted.id), array_agg(deleted.is_delete_marker), array_agg(deleted.metadata)
          INTO deleted_ids, deleted_markers, deleted_metadata
          FROM deleted;
        bulk_deleted := true;
    EXCEPTION
        WHEN OTHERS THEN
            -- User triggers may use insufficient_privilege to block a row.
            IF SQLSTATE <> '42501' AND left(SQLSTATE, 2) IN ('08', '40', '42', '53', '55', '57', '58', 'XX') THEN
                RAISE;
            END IF;
    END;
    IF bulk_deleted THEN
        RETURN QUERY SELECT * FROM unnest(deleted_ids, deleted_markers, deleted_metadata);
        RETURN;
    END IF;

    FOREACH object_id IN ARRAY object_ids LOOP
        BEGIN
            DELETE FROM storage.objects AS object_row
              WHERE object_row.id = object_id AND object_row.archived_at IS NOT NULL
              RETURNING object_row.* INTO deleted_row;
            IF FOUND THEN
                id := deleted_row.id;
                is_delete_marker := deleted_row.is_delete_marker;
                metadata := deleted_row.metadata;
                RETURN NEXT;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                IF SQLSTATE <> '42501' AND left(SQLSTATE, 2) IN ('08', '40', '42', '53', '55', '57', '58', 'XX') THEN
                    RAISE;
                END IF;
        END;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.moreai_worker_append_run_event(p_run_id uuid, p_worker_id text, p_event_key text, p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.outbox_events;
  v_sequence bigint;
  v_event_id uuid := gen_random_uuid();
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
begin
  if p_run_id is null or p_event_key is null or char_length(p_event_key) not between 1 and 200
     or p_event_type is null or p_event_type !~ '^[a-z][a-z0-9_.-]{0,79}$'
     or jsonb_typeof(v_payload) <> 'object' or octet_length(v_payload::text) > 16384 then
    raise exception 'invalid_run_event' using errcode='22023';
  end if;
  if p_worker_id is null or not exists(
    select 1 from public.agent_runs
    where id=p_run_id and status='running' and lease_owner=p_worker_id and lease_expires_at>now()
  ) then
    raise exception 'worker_lease_not_held' using errcode='42501';
  end if;
  insert into public.agent_run_event_counters(run_id,last_sequence)
  values(p_run_id,coalesce((select max(sequence) from public.agent_run_events where run_id=p_run_id),0))
  on conflict(run_id) do nothing;
  perform 1 from public.agent_run_event_counters where run_id=p_run_id for update;

  select * into v_existing from public.outbox_events
    where aggregate_type='agent_run' and aggregate_id=p_run_id and event_key=p_event_key;
  if found then
    if v_existing.payload->>'event_type' <> p_event_type
       or v_existing.payload->'event_payload' <> v_payload then
      raise exception 'run_event_idempotency_conflict' using errcode='22023';
    end if;
    return jsonb_build_object(
      'event_id',v_existing.id,'sequence',v_existing.run_sequence,'duplicate',true
    );
  end if;

  update public.agent_run_event_counters
    set last_sequence=last_sequence+1,updated_at=now()
    where run_id=p_run_id returning last_sequence into v_sequence;

  insert into public.agent_run_events(id,run_id,event_type,sequence,payload,created_at)
    values(v_event_id,p_run_id,p_event_type,v_sequence,v_payload,now());

  insert into public.outbox_events(
    id,aggregate_type,aggregate_id,event_type,payload,status,attempts,available_at,
    created_at,event_key,run_sequence
  ) values(
    v_event_id,'agent_run',p_run_id,'run.event',
    jsonb_build_object(
      'run_id',p_run_id,'event_id',v_event_id,'sequence',v_sequence,
      'event_type',p_event_type,'event_payload',v_payload,'created_at',now()
    ),
    'pending',0,now(),now(),p_event_key,v_sequence
  );

  return jsonb_build_object('event_id',v_event_id,'sequence',v_sequence,'duplicate',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_redeem_partner_access_code(p_code_hash text, p_user_id uuid, p_network_id uuid, p_verification_session_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_code public.partner_access_codes%rowtype; v_verification public.network_verification_sessions%rowtype; v_redemption public.partner_access_code_redemptions%rowtype; v_now timestamptz := now();
begin
 if p_code_hash !~ '^[0-9a-f]{64}$' or length(p_idempotency_key) not between 8 and 160 then raise exception using errcode='22023',message='ACCESS_CODE_INVALID'; end if;
 select * into v_verification from public.network_verification_sessions where id=p_verification_session_id and user_id=p_user_id and network_id=p_network_id and status='verified' and expires_at>v_now and ended_at is null;
 if not found then raise exception using errcode='42501',message='NETWORK_VERIFICATION_REQUIRED'; end if;
 select * into v_code from public.partner_access_codes where code_hash=p_code_hash for update;
 if not found or v_code.status<>'active' then raise exception using errcode='P0002',message='ACCESS_CODE_NOT_AVAILABLE'; end if;
 if v_code.expires_at<=v_now then update public.partner_access_codes set status='expired' where id=v_code.id; raise exception using errcode='P0002',message='ACCESS_CODE_EXPIRED'; end if;
 if v_code.redemption_count>=v_code.max_redemptions then update public.partner_access_codes set status='exhausted' where id=v_code.id; raise exception using errcode='P0002',message='ACCESS_CODE_EXHAUSTED'; end if;
 if v_code.network_id is not null and v_code.network_id<>p_network_id then raise exception using errcode='42501',message='ACCESS_CODE_NETWORK_MISMATCH'; end if;
 if v_code.location_id is not null and not exists(select 1 from public.partner_networks n where n.id=p_network_id and n.location_id=v_code.location_id and n.partner_id=v_code.partner_id) then raise exception using errcode='42501',message='ACCESS_CODE_SCOPE_MISMATCH'; end if;
 select * into v_redemption from public.partner_access_code_redemptions where user_id=p_user_id and idempotency_key=p_idempotency_key;
 if found then if v_redemption.access_code_id<>v_code.id then raise exception using errcode='23505',message='IDEMPOTENCY_KEY_CONFLICT'; end if; return jsonb_build_object('redemption_id',v_redemption.id,'replayed',true,'redeemed_at',v_redemption.redeemed_at); end if;
 insert into public.partner_access_code_redemptions(access_code_id,user_id,network_id,verification_session_id,idempotency_key) values(v_code.id,p_user_id,p_network_id,p_verification_session_id,p_idempotency_key) returning * into v_redemption;
 update public.partner_access_codes set redemption_count=redemption_count+1,status=case when redemption_count+1>=max_redemptions then 'exhausted' else 'active' end where id=v_code.id;
 if v_code.reward_id is not null then update public.campaign_rewards set quantity_claimed=quantity_claimed+1 where id=v_code.reward_id and (quantity_limit is null or quantity_claimed<quantity_limit); if not found then raise exception using errcode='P0001',message='REWARD_QUOTA_EXHAUSTED'; end if; end if;
 insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,scope_id,outcome,metadata) values(p_user_id,'partner.access_code.redeemed','partner_access_code',v_code.id,'partner',v_code.partner_id,'success',jsonb_build_object('network_id',p_network_id,'redemption_id',v_redemption.id));
 return jsonb_build_object('redemption_id',v_redemption.id,'replayed',false,'redeemed_at',v_redemption.redeemed_at,'reward_id',v_code.reward_id,'partner_entitlement_activated',false,'message','Access code redeemed; entitlement activation remains separate.');
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_llm_finalize_request(p_request_id uuid, p_actual_credits numeric, p_settlement_key text, p_provider_response_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    r public.llm_request_records%rowtype;
    v_item jsonb;
    v_usage public.quota_usage%rowtype;
    v_limit numeric;
    v_reserved numeric;
    v_new_used numeric;
begin
    if p_actual_credits is null or p_actual_credits < 0 then
        raise exception 'invalid actual credits' using errcode = '22023';
    end if;

    select * into r from public.llm_request_records where id = p_request_id for update;
    if not found then raise exception 'llm request not found'; end if;
    if r.status = 'succeeded' then
        return pg_catalog.jsonb_build_object('id', r.id, 'status', 'succeeded', 'response_text', r.response_text);
    end if;
    if r.status <> 'provider_succeeded' or r.reservation_id is null then
        raise exception 'llm request is not ready for settlement';
    end if;

    -- Reconcile reserved quota to actual billable credits within each original policy window.
    for v_item in select value from pg_catalog.jsonb_array_elements(coalesce(r.quota_reservation, '[]'::jsonb))
    loop
        v_reserved := (v_item ->> 'reserved_amount')::numeric;
        select * into v_usage
          from public.quota_usage
         where policy_id = (v_item ->> 'policy_id')::uuid
           and scope_type = v_item ->> 'scope_type'
           and scope_id is not distinct from (v_item ->> 'scope_id')::uuid
           and metric_key = v_item ->> 'metric_key'
           and window_start = (v_item ->> 'window_start')::timestamptz
         for update;
        if not found then raise exception 'reserved quota usage row missing'; end if;
        select limit_value into v_limit
          from public.quota_policies
         where id = (v_item ->> 'policy_id')::uuid
         for share;
        if not found then raise exception 'quota policy missing during settlement'; end if;
        v_new_used := v_usage.used_value - v_reserved + p_actual_credits;
        if v_new_used < 0 or v_new_used > v_limit then
            raise exception 'actual usage exceeds reserved quota or policy limit' using errcode = '54000';
        end if;
        update public.quota_usage set used_value = v_new_used, updated_at = now() where id = v_usage.id;
    end loop;

    perform public.moreai_credit_settle(r.reservation_id, p_actual_credits, p_settlement_key);

    insert into public.llm_usage(
        user_id, run_id, provider_key, model_key, request_id, input_tokens, output_tokens,
        estimated_cost, actual_cost, status, idempotency_key, latency_ms, reservation_id, provider_response_id
    )
    values(
        r.user_id, r.run_id, r.provider_key, r.model_key, r.id::text, r.input_tokens, r.output_tokens,
        r.estimated_cost, r.actual_cost, 'succeeded', r.idempotency_key, r.latency_ms, r.reservation_id, p_provider_response_id
    )
    on conflict(user_id, idempotency_key) do nothing;

    update public.llm_request_records set status = 'succeeded', updated_at = now() where id = r.id;
    return pg_catalog.jsonb_build_object('id', r.id, 'status', 'succeeded', 'response_text', r.response_text);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_llm_fail_request(p_request_id uuid, p_error_code text, p_release boolean DEFAULT true, p_release_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    r public.llm_request_records%rowtype;
    v_item jsonb;
    v_usage public.quota_usage%rowtype;
    v_reserved numeric;
begin
    select * into r from public.llm_request_records where id = p_request_id for update;
    if not found then raise exception 'llm request not found'; end if;
    if r.status in ('succeeded', 'failed') then
        return pg_catalog.jsonb_build_object('id', r.id, 'status', r.status);
    end if;

    if p_release then
        if r.reservation_id is not null then
            perform public.moreai_credit_release(r.reservation_id, coalesce(p_release_key, 'llm-release:' || r.id::text));
        end if;
        for v_item in select value from pg_catalog.jsonb_array_elements(coalesce(r.quota_reservation, '[]'::jsonb))
        loop
            v_reserved := (v_item ->> 'reserved_amount')::numeric;
            select * into v_usage
              from public.quota_usage
             where policy_id = (v_item ->> 'policy_id')::uuid
               and scope_type = v_item ->> 'scope_type'
               and scope_id is not distinct from (v_item ->> 'scope_id')::uuid
               and metric_key = v_item ->> 'metric_key'
               and window_start = (v_item ->> 'window_start')::timestamptz
             for update;
            if found then
                update public.quota_usage
                   set used_value = case when used_value >= v_reserved then used_value - v_reserved else 0 end,
                       updated_at = now()
                 where id = v_usage.id;
            end if;
        end loop;
        update public.llm_request_records set status = 'failed', error_code = p_error_code, updated_at = now() where id = r.id;
    else
        -- Unknown provider outcome retains the reservation to prevent duplicate free execution.
        update public.llm_request_records set status = 'unknown', error_code = p_error_code, updated_at = now() where id = r.id;
    end if;
    return pg_catalog.jsonb_build_object('id', r.id, 'status', case when p_release then 'failed' else 'unknown' end);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_consume_tool_approval(p_run_id uuid, p_user_id uuid, p_tool_key text, p_arguments_hash text)
