CREATE OR REPLACE FUNCTION public.moreai_enqueue_chat_run(p_user_id uuid, p_conversation_id uuid, p_content text, p_agent_key text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
begin
    if p_user_id is null
       or p_conversation_id is null
       or p_content is null
       or length(btrim(p_content)) = 0
       or length(p_content) > 100000
       or p_agent_key is null
       or p_idempotency_key is null
       or length(p_idempotency_key) < 12
       or length(p_idempotency_key) > 128
       or p_agent_key not in ('manus', 'planning', 'toolcall') then
        raise exception 'invalid chat enqueue request' using errcode = '22023';
    end if;

    select *
      into v_conversation
      from public.conversations
     where id = p_conversation_id
       and user_id = p_user_id
     for update;

    if not found then
        raise exception 'conversation not found' using errcode = '42501';
    end if;

    select *
      into v_run
      from public.agent_runs
     where user_id = p_user_id
       and idempotency_key = p_idempotency_key;

    if found then
        return pg_catalog.jsonb_build_object(
            'run', pg_catalog.to_jsonb(v_run),
            'message', null,
            'replayed', true
        );
    end if;

    insert into public.conversation_messages (
        conversation_id, user_id, role, content, metadata
    ) values (
        p_conversation_id, p_user_id, 'user', p_content, '{}'::jsonb
    )
    returning * into v_message;

    insert into public.agent_runs (
        user_id, workspace_id, conversation_id, status,
        idempotency_key, input, max_attempts
    ) values (
        p_user_id,
        v_conversation.workspace_id,
        p_conversation_id,
        'queued',
        p_idempotency_key,
        pg_catalog.jsonb_build_object(
            'prompt', p_content,
            'agent_key', p_agent_key,
            'conversation_id', p_conversation_id,
            'message_id', v_message.id
        ),
        3
    )
    returning * into v_run;

    update public.conversation_messages
       set run_id = v_run.id
     where id = v_message.id
       and user_id = p_user_id;
    v_message.run_id := v_run.id;

    return pg_catalog.jsonb_build_object(
        'run', pg_catalog.to_jsonb(v_run),
        'message', pg_catalog.to_jsonb(v_message),
        'replayed', false
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_customer_workspace_restore_file(p_user_id uuid, p_workspace_id uuid, p_file_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_file public.agent_workspace_files%rowtype;
begin
  if p_user_id is null or p_workspace_id is null or p_file_id is null
     or p_expected_version is null or p_expected_version < 1 then
    raise exception 'workspace_file_restore_arguments_invalid' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.workspaces w
    where w.id = p_workspace_id and w.status = 'active'
      and (w.owner_user_id = p_user_id or exists (
        select 1 from public.workspace_members m
        where m.workspace_id = w.id and m.user_id = p_user_id and m.status = 'active'
      ))
  ) then raise exception 'workspace_membership_required' using errcode = '42501'; end if;
  select * into v_file from public.agent_workspace_files
  where id = p_file_id and workspace_id = p_workspace_id for update;
  if not found then raise exception 'workspace_file_not_found' using errcode = 'P0002'; end if;
  if v_file.version <> p_expected_version then raise exception 'workspace_version_conflict' using errcode = '40001'; end if;
  if v_file.deleted_at is null then raise exception 'workspace_file_not_deleted' using errcode = '22023'; end if;
  if v_file.pending_token is not null or v_file.storage_path is null
     or v_file.sha256 is null or v_file.size_bytes is null then
    raise exception 'workspace_file_not_committed_or_write_in_progress' using errcode = '40001';
  end if;
  update public.agent_workspace_files
     set deleted_at = null, version = version + 1, updated_at = now()
   where id = p_file_id and workspace_id = p_workspace_id
     and version = p_expected_version and deleted_at is not null and pending_token is null
   returning * into v_file;
  if not found then raise exception 'workspace_file_restore_fence_lost' using errcode = '40001'; end if;
  return jsonb_build_object('id',v_file.id,'workspace_id',v_file.workspace_id,'path',v_file.path,
    'version',v_file.version,'deleted_at',v_file.deleted_at,'status','restored');
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_worker_finish_run(p_run_id uuid, p_worker_id text, p_status text, p_output jsonb DEFAULT NULL::jsonb, p_error jsonb DEFAULT NULL::jsonb, p_retry_delay_seconds integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.agent_runs%rowtype;
  next_status text;
  dead boolean := false;
  event_type text;
  event_key text;
begin
  if p_status not in ('succeeded','failed','cancelled') then
    raise exception 'invalid terminal status';
  end if;
  select * into r from public.agent_runs where id=p_run_id for update;
  if not found then raise exception 'run not found'; end if;
  if r.status in ('succeeded','failed','cancelled') then
    return jsonb_build_object('run_id',r.id,'status',r.status);
  end if;
  if r.lease_owner is distinct from p_worker_id or r.lease_expires_at <= now() then
    raise exception 'worker lease mismatch';
  end if;
  if r.cancel_requested_at is not null then
    next_status := 'cancelled';
  elsif p_status='failed' and r.attempt<r.max_attempts then
    next_status := 'queued';
  elsif p_status='failed' then
    next_status := 'failed'; dead := true;
  else
    next_status := p_status;
  end if;
  event_type := case when dead then 'worker.dead_lettered' else 'worker.'||next_status end;
  event_key := 'worker.finish:'||r.attempt::text||':'||next_status;
  perform public.moreai_worker_append_run_event(
    p_run_id,p_worker_id,event_key,event_type,
    jsonb_build_object('attempt',r.attempt,'error_code',
      case when p_error is null then null else coalesce(p_error->>'code','execution_failed') end)
  );
  if next_status='queued' then
    update public.agent_runs set status=next_status,error=p_error,
      available_at=now()+make_interval(secs=>greatest(1,least(p_retry_delay_seconds,3600))),
      lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now()
      where id=r.id;
  else
    update public.agent_runs set status=next_status,output=p_output,error=p_error,
      finished_at=now(),dead_lettered_at=case when dead then now() else dead_lettered_at end,
      lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now()
      where id=r.id;
  end if;
  return jsonb_build_object('run_id',r.id,'status',next_status,'attempt',r.attempt,'dead_lettered',dead);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_worker_pause_for_tool_approval(p_run_id uuid, p_user_id uuid, p_worker_id text, p_tool_key text, p_arguments_hash text, p_summary text, p_expires_in_seconds integer DEFAULT 900)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.agent_runs%rowtype; a_id uuid; p public.agent_run_approval_pauses%rowtype; v_key text; v_state jsonb;
begin
 select * into r from public.agent_runs where id=p_run_id for update;
 if not found or r.user_id is distinct from p_user_id then raise exception 'approval_run_owner_mismatch' using errcode='42501'; end if;
 if r.status<>'running' or r.lease_owner is distinct from p_worker_id or r.lease_expires_at<=now() then raise exception 'worker_lease_not_held' using errcode='42501'; end if;
 select * into p from public.agent_run_approval_pauses where run_id=p_run_id and tool_key=p_tool_key and arguments_hash=p_arguments_hash for update;
 if found then
  if p.status in ('approved','denied','expired','consumed') then return jsonb_build_object('approval_id',p.approval_id,'status',p.status,'resumed',true); end if;
  if p.status='pending' then raise exception 'approval_already_pending' using errcode='55000'; end if;
 end if;
 a_id:=public.moreai_request_tool_approval(p_run_id,p_user_id,p_tool_key,p_arguments_hash,p_summary,p_expires_in_seconds);
 v_key:='approval.pause.'||a_id::text;
 insert into public.agent_run_approval_pauses(run_id,approval_id,user_id,tool_key,arguments_hash,status,checkpoint_key)
 values(p_run_id,a_id,p_user_id,p_tool_key,p_arguments_hash,'pending',v_key)
 on conflict(run_id,tool_key,arguments_hash) do update set approval_id=excluded.approval_id,status='pending',checkpoint_key=excluded.checkpoint_key,created_at=now(),decided_at=null,resumed_at=null returning * into p;
 v_state:=jsonb_build_object('approval_id',a_id,'tool_key',p_tool_key,'arguments_hash',p_arguments_hash,'status','pending','attempt',r.attempt,'checkpoint_key',v_key);
 insert into public.agent_run_checkpoints(run_id,checkpoint_key,state) values(p_run_id,v_key,v_state)
 on conflict(run_id,checkpoint_key) do update set state=excluded.state,created_at=now();
 update public.agent_runs set status='waiting_approval',last_checkpoint_key=v_key,lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now()
 where id=p_run_id and status='running' and lease_owner=p_worker_id;
 return jsonb_build_object('approval_id',a_id,'status','pending','checkpoint_key',v_key);
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_worker_claim_run(p_worker_id text, p_lease_seconds integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.agent_runs%rowtype; seq bigint; d record; v_was_resume boolean;
begin
 if p_worker_id is null or length(p_worker_id)<8 or length(p_worker_id)>128 or p_lease_seconds not between 15 and 900 then raise exception 'invalid worker claim'; end if;
 for d in select p.id,p.run_id,p.approval_id,p.checkpoint_key from public.agent_run_approval_pauses p join public.agent_tool_approvals a on a.id=p.approval_id
  where p.status='pending' and a.expires_at<=now() for update of p,a skip locked
 loop
  update public.agent_tool_approvals set status='expired',decided_at=now() where id=d.approval_id and status='pending';
  update public.agent_run_approval_pauses set status='expired',decided_at=now() where id=d.id and status='pending';
  update public.agent_runs set status=case when cancel_requested_at is not null then 'cancelled' else 'queued' end,
   resume_pending=(cancel_requested_at is null),finished_at=case when cancel_requested_at is not null then now() else finished_at end,available_at=now(),updated_at=now()
   where id=d.run_id and status='waiting_approval';
  update public.agent_run_checkpoints set state=state||jsonb_build_object('status','expired','resume_pending',true),created_at=now()
   where run_id=d.run_id and checkpoint_key=d.checkpoint_key;
 end loop;
 for d in update public.agent_runs set status='failed',finished_at=now(),dead_lettered_at=now(),lease_owner=null,lease_expires_at=null,updated_at=now()
  where status='running' and lease_expires_at<now() and attempt>=max_attempts returning id
 loop
  select coalesce(max(sequence),0)+1 into seq from public.agent_run_events where run_id=d.id;
  insert into public.agent_run_events(run_id,event_type,sequence,payload) values(d.id,'worker.dead_lettered',seq,'{"reason":"lease_expired_max_attempts"}'::jsonb);
 end loop;
 select * into r from public.agent_runs where ((status='queued' and available_at<=now()) or (status='running' and lease_expires_at<now()))
  and attempt<max_attempts and cancel_requested_at is null
  and not exists(select 1 from public.agent_run_approval_pauses p where p.run_id=agent_runs.id and p.status='pending')
  order by available_at,created_at for update skip locked limit 1;
 if not found then return null; end if;
 v_was_resume:=r.resume_pending;
 update public.agent_runs set status='running',attempt=attempt+case when resume_pending then 0 else 1 end,resume_pending=false,
  lease_owner=p_worker_id,lease_expires_at=now()+make_interval(secs=>p_lease_seconds),heartbeat_at=now(),
  started_at=coalesce(started_at,now()),updated_at=now() where id=r.id returning * into r;
 update public.agent_run_approval_pauses set resumed_at=coalesce(resumed_at,now()) where run_id=r.id and status in ('approved','denied','expired');
 select coalesce(max(sequence),0)+1 into seq from public.agent_run_events where run_id=r.id;
 insert into public.agent_run_events(run_id,event_type,sequence,payload) values(r.id,'worker.claimed',seq,
  jsonb_build_object('worker_id',p_worker_id,'attempt',r.attempt,'lease_seconds',p_lease_seconds,'approval_resume',v_was_resume));
 return jsonb_build_object('id',r.id,'user_id',r.user_id,'workspace_id',r.workspace_id,'conversation_id',r.conversation_id,
  'agent_definition_id',r.agent_definition_id,'status',r.status,'attempt',r.attempt,'max_attempts',r.max_attempts,
  'input',r.input,'lease_owner',r.lease_owner,'lease_expires_at',r.lease_expires_at);
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_workspace_begin_write(p_run_id uuid, p_worker_id text, p_user_id uuid, p_workspace_id uuid, p_path text, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.agent_runs%rowtype; f public.agent_workspace_files%rowtype; v_token uuid; v_version bigint;
begin
 if p_path is null or length(p_path) not between 1 and 512 or p_expected_version<0 then raise exception 'workspace_write_arguments_invalid' using errcode='22023'; end if;
 select * into r from public.agent_runs where id=p_run_id for update;
 if not found or r.user_id<>p_user_id or r.workspace_id is distinct from p_workspace_id
  or r.status<>'running' or r.lease_owner is distinct from p_worker_id or r.lease_expires_at<=now()
 then raise exception 'workspace_run_scope_or_lease_invalid' using errcode='42501'; end if;
 if not exists(select 1 from public.workspaces w where w.id=p_workspace_id and w.status='active'
  and (w.owner_user_id=p_user_id or exists(select 1 from public.workspace_members m where m.workspace_id=w.id and m.user_id=p_user_id and m.status='active')))
 then raise exception 'workspace_membership_required' using errcode='42501'; end if;
 select * into f from public.agent_workspace_files where workspace_id=p_workspace_id and path=p_path for update;
 if not found then
  if p_expected_version<>0 then raise exception 'workspace_version_conflict' using errcode='40001'; end if;
  insert into public.agent_workspace_files(workspace_id,user_id,path) values(p_workspace_id,p_user_id,p_path) returning * into f;
 end if;
 if f.version<>p_expected_version then raise exception 'workspace_version_conflict' using errcode='40001'; end if;
 if f.pending_token is not null and f.pending_expires_at>now() then raise exception 'workspace_write_in_progress' using errcode='40001'; end if;
 v_token:=gen_random_uuid(); v_version:=f.version+1;
 update public.agent_workspace_files set pending_version=v_version,pending_token=v_token,pending_run_id=p_run_id,
  pending_expires_at=now()+interval '5 minutes',updated_at=now() where id=f.id returning * into f;
 return jsonb_build_object('version',v_version,'token',v_token,'current_version',f.version,'storage_path',
  p_user_id::text||'/workspaces/'||p_workspace_id::text||'/versions/'||v_version::text||'/'||p_path);
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_workspace_commit_write(p_run_id uuid, p_worker_id text, p_user_id uuid, p_workspace_id uuid, p_path text, p_token uuid, p_version bigint, p_storage_path text, p_sha256 text, p_size_bytes bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.agent_runs%rowtype; f public.agent_workspace_files%rowtype;
begin
 select * into r from public.agent_runs where id=p_run_id for update;
 if not found or r.user_id<>p_user_id or r.workspace_id is distinct from p_workspace_id
  or r.status<>'running' or r.lease_owner is distinct from p_worker_id or r.lease_expires_at<=now()
 then raise exception 'workspace_run_scope_or_lease_invalid' using errcode='42501'; end if;
 if p_sha256 !~ '^[0-9a-f]{64}$' or p_size_bytes not between 0 and 2000000 then raise exception 'workspace_file_metadata_invalid' using errcode='22023'; end if;
 update public.agent_workspace_files set version=p_version,pending_version=null,pending_token=null,pending_run_id=null,
  pending_expires_at=null,storage_path=p_storage_path,sha256=p_sha256,size_bytes=p_size_bytes,updated_at=now()
 where workspace_id=p_workspace_id and path=p_path and pending_token=p_token and pending_version=p_version
  and pending_run_id=p_run_id and pending_expires_at>now()
 returning * into f;
