CREATE OR REPLACE FUNCTION public.moreai_worker_request_cancel(p_run_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.agent_runs%rowtype; seq bigint; next_status text; event_type text; v_event_key text; v_event uuid:=gen_random_uuid(); v_payload jsonb;
begin
 select * into r from public.agent_runs where id=p_run_id and user_id=p_user_id for update;
 if not found then raise exception 'run not found' using errcode='P0002'; end if;
 if r.status in ('succeeded','failed','cancelled') then return jsonb_build_object('run_id',r.id,'status',r.status); end if;

 if r.status='queued' or r.status='waiting_approval' then
  next_status:='cancelled';
  update public.agent_runs set status='cancelled',cancel_requested_at=coalesce(cancel_requested_at,now()),
   finished_at=now(),lease_owner=null,lease_expires_at=null,heartbeat_at=null,updated_at=now()
   where id=r.id;
  update public.agent_tool_approvals set status='denied',decided_at=coalesce(decided_at,now()),decided_by=p_user_id
   where run_id=r.id and status='pending';
  update public.agent_run_approval_pauses set status='denied',decided_at=coalesce(decided_at,now())
   where run_id=r.id and status='pending';
  update public.agent_run_checkpoints set state=state||jsonb_build_object('status','cancelled','resume_pending',false),created_at=now()
   where run_id=r.id and checkpoint_key in (select checkpoint_key from public.agent_run_approval_pauses where run_id=r.id);
  event_type:='run.cancelled';
 else
  next_status:='cancel_requested';
  update public.agent_runs set cancel_requested_at=coalesce(cancel_requested_at,now()),updated_at=now() where id=r.id;
  event_type:='run.cancel_requested';
 end if;
 v_event_key:='user.cancel:'||r.id::text;
 v_payload:=jsonb_build_object('status',next_status,'requested_by',p_user_id);
 insert into public.agent_run_event_counters(run_id,last_sequence)
  values(r.id,coalesce((select max(sequence) from public.agent_run_events where run_id=r.id),0))
  on conflict(run_id) do nothing;
 perform 1 from public.agent_run_event_counters where run_id=r.id for update;
 if not exists(select 1 from public.outbox_events o where aggregate_type='agent_run' and aggregate_id=r.id and o.event_key=v_event_key) then
  update public.agent_run_event_counters set last_sequence=last_sequence+1,updated_at=now()
   where run_id=r.id returning last_sequence into seq;
  insert into public.agent_run_events(id,run_id,event_type,sequence,payload,created_at)
   values(v_event,r.id,event_type,seq,v_payload,now());
  insert into public.outbox_events(id,aggregate_type,aggregate_id,event_type,payload,status,attempts,available_at,created_at,event_key,run_sequence)
   values(v_event,'agent_run',r.id,'run.event',jsonb_build_object('run_id',r.id,'event_id',v_event,'sequence',seq,
    'event_type',event_type,'event_payload',v_payload,'created_at',now()),'pending',0,now(),now(),v_event_key,seq);
 end if;
 return jsonb_build_object('run_id',r.id,'status',next_status);
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_customer_workspace_delete_file(p_user_id uuid, p_workspace_id uuid, p_file_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_file public.agent_workspace_files%rowtype;
begin
  if p_user_id is null or p_workspace_id is null or p_file_id is null
     or p_expected_version is null or p_expected_version < 0 then
    raise exception 'workspace_file_delete_arguments_invalid' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.workspaces w where w.id=p_workspace_id and w.status='active'
      and (w.owner_user_id=p_user_id or exists (
        select 1 from public.workspace_members m where m.workspace_id=w.id
          and m.user_id=p_user_id and m.status='active'
      ))
  ) then raise exception 'workspace_membership_required' using errcode='42501'; end if;
  select * into v_file from public.agent_workspace_files
    where id=p_file_id and workspace_id=p_workspace_id for update;
  if not found then raise exception 'workspace_file_not_found' using errcode='P0002'; end if;
  if v_file.version<>p_expected_version then raise exception 'workspace_version_conflict' using errcode='40001'; end if;
  if v_file.pending_token is not null then raise exception 'workspace_write_in_progress' using errcode='40001'; end if;
  if v_file.deleted_at is null then
    if v_file.version>0 and v_file.storage_path is not null and v_file.sha256 is not null and v_file.size_bytes is not null then
      insert into public.agent_workspace_file_versions(
        workspace_id,user_id,path,version,storage_path,sha256,size_bytes,committed_at
      ) values (v_file.workspace_id,v_file.user_id,v_file.path,v_file.version,
        v_file.storage_path,v_file.sha256,v_file.size_bytes,v_file.updated_at)
      on conflict(workspace_id,path,version) do nothing;
    end if;
    update public.agent_workspace_files set deleted_at=now(),updated_at=now()
      where id=p_file_id and workspace_id=p_workspace_id and version=p_expected_version
        and pending_token is null returning * into v_file;
    if not found then raise exception 'workspace_file_delete_fence_lost' using errcode='40001'; end if;
  end if;
  return jsonb_build_object('id',v_file.id,'workspace_id',v_file.workspace_id,'path',v_file.path,
    'version',v_file.version,'deleted_at',v_file.deleted_at,'status','deleted');
end;
$function$

