CREATE OR REPLACE FUNCTION public.moreai_request_tool_approval(p_run_id uuid, p_user_id uuid, p_tool_key text, p_arguments_hash text, p_summary text, p_expires_in_seconds integer DEFAULT 900)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id uuid;
begin
  if p_tool_key not in (
       'bash','python_execute','browser_use','planning_step',
       'browser','file_read','file_write','file_edit','workspace_restore_version'
     )
     or p_arguments_hash !~ '^[0-9a-f]{64}$'
     or p_expires_in_seconds < 60 or p_expires_in_seconds > 3600
     or char_length(p_summary) not between 1 and 1000 then
    raise exception 'invalid_tool_approval_request' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.agent_runs r
    where r.id=p_run_id and r.user_id=p_user_id
  ) then
    raise exception 'approval_run_owner_mismatch' using errcode = '42501';
  end if;
  update public.agent_tool_approvals
     set status='expired'
   where run_id=p_run_id and tool_key=p_tool_key and arguments_hash=p_arguments_hash
     and status in ('pending','approved') and expires_at <= now();
  select id into v_id from public.agent_tool_approvals
   where run_id=p_run_id and tool_key=p_tool_key and arguments_hash=p_arguments_hash
     and status in ('pending','approved') and expires_at > now()
   order by requested_at desc
   limit 1;
  if v_id is not null then return v_id; end if;
  insert into public.agent_tool_approvals(run_id,user_id,tool_key,arguments_hash,summary,expires_at)
  values(p_run_id,p_user_id,p_tool_key,p_arguments_hash,p_summary,now()+make_interval(secs=>p_expires_in_seconds))
  returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_set_customer_learning_progress(p_user_id uuid, p_module_key text, p_lesson_key text, p_completed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.customer_learning_progress%rowtype;
begin
 if p_module_key !~ '^[a-z0-9][a-z0-9_-]{0,79}$' or char_length(p_lesson_key) not between 1 and 512 then
   raise exception 'invalid_learning_progress_key' using errcode='22023';
 end if;
 if p_completed then
   insert into public.customer_learning_progress(user_id,module_key,lesson_key,completed_at,updated_at)
   values(p_user_id,p_module_key,p_lesson_key,now(),now())
   on conflict(user_id,module_key,lesson_key) do update set completed_at=now(),updated_at=now()
   returning * into v_row;
   return jsonb_build_object('module_key',v_row.module_key,'lesson_key',v_row.lesson_key,'completed',true,'completed_at',v_row.completed_at);
 else
   delete from public.customer_learning_progress
    where user_id=p_user_id and module_key=p_module_key and lesson_key=p_lesson_key;
   return jsonb_build_object('module_key',p_module_key,'lesson_key',p_lesson_key,'completed',false,'completed_at',null);
 end if;
end; $function$

CREATE OR REPLACE FUNCTION public.moreai_customer_workspace_commit_upload(p_user_id uuid, p_workspace_id uuid, p_path text, p_expected_version bigint, p_idempotency_key text, p_storage_path text, p_sha256 text, p_size_bytes bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace public.workspaces%rowtype;
  v_file public.agent_workspace_files%rowtype;
  v_intent public.customer_workspace_upload_idempotency%rowtype;
  v_next_version bigint;
  v_expected_storage_path text;
  v_result jsonb;
begin
  if p_user_id is null or p_workspace_id is null
     or p_path is null or length(p_path) not between 1 and 512
     or p_expected_version is null or p_expected_version < 0
     or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_size_bytes is null or p_size_bytes not between 1 and 2000000 then
    raise exception 'workspace_upload_arguments_invalid' using errcode = '22023';
  end if;

  select * into v_workspace
    from public.workspaces
   where id = p_workspace_id and status = 'active'
     and (owner_user_id = p_user_id or exists (
       select 1 from public.workspace_members m
        where m.workspace_id = p_workspace_id
          and m.user_id = p_user_id and m.status = 'active'
     ));
  if not found then
    raise exception 'workspace_membership_required' using errcode = '42501';
  end if;

  v_next_version := p_expected_version + 1;
  v_expected_storage_path := p_user_id::text || '/workspaces/' ||
    p_workspace_id::text || '/versions/' || v_next_version::text || '/' || p_path;
  if p_storage_path is distinct from v_expected_storage_path then
    raise exception 'workspace_upload_storage_path_invalid' using errcode = '22023';
  end if;

  insert into public.customer_workspace_upload_idempotency (
    user_id, idempotency_key, workspace_id, path, expected_version,
    storage_path, sha256, size_bytes
  ) values (
    p_user_id, p_idempotency_key, p_workspace_id, p_path, p_expected_version,
    p_storage_path, p_sha256, p_size_bytes
  ) on conflict (user_id, idempotency_key) do nothing;

  select * into v_intent
    from public.customer_workspace_upload_idempotency
   where user_id = p_user_id and idempotency_key = p_idempotency_key
   for update;

  if v_intent.workspace_id <> p_workspace_id
     or v_intent.path <> p_path
     or v_intent.expected_version <> p_expected_version
     or v_intent.storage_path <> p_storage_path
     or v_intent.sha256 <> p_sha256
     or v_intent.size_bytes <> p_size_bytes then
    raise exception 'workspace_upload_idempotency_key_reused' using errcode = '22023';
  end if;

  if v_intent.committed_at is not null then
    return coalesce(v_intent.result, '{}'::jsonb) || jsonb_build_object('replayed', true);
  end if;

  insert into public.agent_workspace_files (workspace_id, user_id, path, version)
  values (p_workspace_id, p_user_id, p_path, 0)
  on conflict (workspace_id, path) do nothing;

  update public.agent_workspace_files
     set version = v_next_version,
         storage_path = p_storage_path,
         sha256 = p_sha256,
         size_bytes = p_size_bytes,
         updated_at = now()
   where workspace_id = p_workspace_id
     and path = p_path
     and version = p_expected_version
     and pending_token is null
     and pending_version is null
     and pending_run_id is null
     and deleted_at is null
  returning * into v_file;

  if not found then
    raise exception 'workspace_version_conflict_or_write_in_progress' using errcode = '40001';
  end if;

  v_result := jsonb_build_object(
    'workspace_id', p_workspace_id,
    'file_id', v_file.id,
    'path', v_file.path,
    'version', v_file.version,
    'storage_path', v_file.storage_path,
    'sha256', v_file.sha256,
    'size_bytes', v_file.size_bytes,
    'updated_at', v_file.updated_at,
    'replayed', false
  );

  update public.customer_workspace_upload_idempotency
     set result = v_result, committed_at = now()
   where user_id = p_user_id and idempotency_key = p_idempotency_key;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_workspace_commit_execution_snapshot(p_run_id uuid, p_worker_id text, p_user_id uuid, p_workspace_id uuid, p_bucket text, p_operation_key text, p_changes jsonb, p_deletes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.agent_runs%rowtype;
  f public.agent_workspace_files%rowtype;
  item jsonb;
  v_path text;
  v_storage_path text;
  v_expected bigint;
  v_next bigint;
  v_size bigint;
  v_sha text;
  v_saved jsonb := '[]'::jsonb;
  v_deleted jsonb := '[]'::jsonb;
  v_result jsonb;
  v_count integer;
  v_distinct integer;
begin
  if p_run_id is null or p_user_id is null or p_workspace_id is null
     or p_worker_id is null or length(p_worker_id) not between 8 and 128
     or p_bucket is null or length(p_bucket) not between 1 and 100
     or p_operation_key is null or p_operation_key !~ '^[0-9a-f]{64}$'
     or p_changes is null or jsonb_typeof(p_changes) is distinct from 'array'
     or p_deletes is null or jsonb_typeof(p_deletes) is distinct from 'array'
     or jsonb_array_length(p_changes) > 200
     or jsonb_array_length(p_deletes) > 200
     or jsonb_array_length(p_changes) + jsonb_array_length(p_deletes) > 200 then
    raise exception 'workspace_execution_commit_arguments_invalid' using errcode='22023';
  end if;

  select * into r from public.agent_runs where id=p_run_id for update;
  if not found or r.user_id<>p_user_id or r.workspace_id is distinct from p_workspace_id then
    raise exception 'workspace_run_scope_invalid' using errcode='42501';
  end if;

  -- A retry after a lost HTTP response returns the already committed result.
  select result into v_result
    from public.agent_workspace_execution_commits
    where run_id=p_run_id and operation_key=p_operation_key
      and user_id=p_user_id and workspace_id=p_workspace_id;
  if found then
    return v_result;
  end if;

  if r.status<>'running' or r.lease_owner is distinct from p_worker_id
     or r.lease_expires_at is null or r.lease_expires_at<=now() then
    raise exception 'workspace_run_scope_or_lease_invalid' using errcode='42501';
  end if;
  if not exists (
    select 1 from public.workspaces w
    where w.id=p_workspace_id and w.status='active'
      and (w.owner_user_id=p_user_id or exists (
        select 1 from public.workspace_members m
        where m.workspace_id=w.id and m.user_id=p_user_id and m.status='active'
      ))
  ) then
    raise exception 'workspace_membership_required' using errcode='42501';
  end if;
  if not exists(select 1 from storage.buckets b where b.id=p_bucket and b.public=false) then
    raise exception 'workspace_bucket_must_be_private' using errcode='42501';
  end if;

  select count(*), count(distinct x.path)
    into v_count, v_distinct
    from (
      select value->>'path' as path from jsonb_array_elements(p_changes)
      union all
      select value->>'path' as path from jsonb_array_elements(p_deletes)
    ) x;
  if v_count <> v_distinct then
    raise exception 'workspace_execution_duplicate_path' using errcode='22023';
  end if;

  -- Deterministic path ordering reduces lock-order inversions between runs.
  for item in
    select value from jsonb_array_elements(p_changes)
    order by value->>'path'
  loop
    v_path := item->>'path';
    if v_path is null or length(v_path) not between 1 and 512
       or position(chr(92) in v_path)>0
       or v_path ~ '(^/|//|(^|/)\.\.?(/|$))'
       or v_path !~ '^[A-Za-z0-9._ -]+(/[A-Za-z0-9._ -]+)*$'
       or coalesce(item->>'expected_version','') !~ '^(0|[1-9][0-9]{0,18})$'
       or coalesce(item->>'size_bytes','') !~ '^(0|[1-9][0-9]{0,6})$'
       or coalesce(item->>'sha256','') !~ '^[0-9a-f]{64}$' then
      raise exception 'workspace_execution_change_invalid' using errcode='22023';
    end if;
    v_expected := (item->>'expected_version')::bigint;
    v_size := (item->>'size_bytes')::bigint;
    v_sha := item->>'sha256';
    if v_expected >= 9223372036854775807 or v_size > 2000000 then
      raise exception 'workspace_execution_change_limit_exceeded' using errcode='22023';
    end if;
    v_next := v_expected + 1;
    v_storage_path := p_user_id::text||'/workspaces/'||p_workspace_id::text
      ||'/versions/'||v_next::text||'/'||v_path;
    if item->>'storage_path' is distinct from v_storage_path then
      raise exception 'workspace_execution_storage_path_invalid' using errcode='22023';
    end if;
    if not exists(select 1 from storage.objects o where o.bucket_id=p_bucket and o.name=v_storage_path) then
      raise exception 'workspace_execution_object_missing' using errcode='P0002';
    end if;

    select * into f from public.agent_workspace_files
      where workspace_id=p_workspace_id and path=v_path for update;
    if not found then
      if v_expected<>0 then
        raise exception 'workspace_version_conflict' using errcode='40001';
      end if;
      insert into public.agent_workspace_files(
        workspace_id,user_id,path,version,storage_path,sha256,size_bytes,updated_at
      ) values (
        p_workspace_id,p_user_id,v_path,1,v_storage_path,v_sha,v_size,now()
      );
    else
      if f.user_id<>p_user_id or f.deleted_at is not null then
        raise exception 'workspace_execution_path_not_active' using errcode='40001';
      end if;
      if f.version<>v_expected or f.pending_token is not null then
        raise exception 'workspace_version_conflict' using errcode='40001';
      end if;
      update public.agent_workspace_files
        set version=v_next,storage_path=v_storage_path,sha256=v_sha,
            size_bytes=v_size,updated_at=now()
        where id=f.id and version=v_expected and pending_token is null;
      if not found then
        raise exception 'workspace_execution_write_fence_lost' using errcode='40001';
      end if;
    end if;
    v_saved := v_saved || jsonb_build_array(jsonb_build_object(
      'path',v_path,'version',v_next,'sha256',v_sha,'size_bytes',v_size
    ));
  end loop;

  for item in
    select value from jsonb_array_elements(p_deletes)
    order by value->>'path'
  loop
    v_path := item->>'path';
    if v_path is null or length(v_path) not between 1 and 512
       or position(chr(92) in v_path)>0
       or v_path ~ '(^/|//|(^|/)\.\.?(/|$))'
       or v_path !~ '^[A-Za-z0-9._ -]+(/[A-Za-z0-9._ -]+)*$'
       or coalesce(item->>'expected_version','') !~ '^[1-9][0-9]{0,18}$' then
      raise exception 'workspace_execution_delete_invalid' using errcode='22023';
    end if;
    v_expected := (item->>'expected_version')::bigint;
    select * into f from public.agent_workspace_files
      where workspace_id=p_workspace_id and path=v_path for update;
    if not found or f.user_id<>p_user_id or f.deleted_at is not null
       or f.version<>v_expected or f.pending_token is not null
       or f.storage_path is null or f.sha256 is null or f.size_bytes is null then
      raise exception 'workspace_execution_delete_conflict' using errcode='40001';
    end if;
    insert into public.agent_workspace_file_versions(
      workspace_id,user_id,path,version,storage_path,sha256,size_bytes,committed_at
    ) values (
      f.workspace_id,f.user_id,f.path,f.version,f.storage_path,f.sha256,f.size_bytes,f.updated_at
    ) on conflict(workspace_id,path,version) do nothing;
    update public.agent_workspace_files
      set deleted_at=now(),updated_at=now()
      where id=f.id and version=v_expected and deleted_at is null and pending_token is null;
    if not found then
      raise exception 'workspace_execution_delete_fence_lost' using errcode='40001';
    end if;
    v_deleted := v_deleted || jsonb_build_array(jsonb_build_object(
      'path',v_path,'version',v_expected,'deleted',true
    ));
  end loop;

  v_result := jsonb_build_object(
    'saved',v_saved,'deleted',v_deleted,
    'saved_count',jsonb_array_length(v_saved),
    'deleted_count',jsonb_array_length(v_deleted),
    'atomic',true
  );
  insert into public.agent_workspace_execution_commits(
    run_id,operation_key,user_id,workspace_id,result
  ) values (p_run_id,p_operation_key,p_user_id,p_workspace_id,v_result);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_customer_knowledge_chunk_count(p_user_id uuid, p_document_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_count bigint;
begin
  if p_user_id is null or p_document_id is null then
    raise exception 'knowledge_chunk_count_arguments_invalid' using errcode='22023';
  end if;
  if not exists(select 1 from public.knowledge_documents d where d.id=p_document_id and d.owner_user_id=p_user_id) then
    raise exception 'knowledge_document_not_found_or_not_owned' using errcode='42501';
  end if;
  select count(*)::bigint into v_count from public.knowledge_chunks c
    where c.document_id=p_document_id and c.owner_user_id=p_user_id;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_customer_clear_personal_memory(p_user_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_deleted bigint;
begin
  if p_user_id is null then
    raise exception 'memory_clear_user_required' using errcode = '22023';
  end if;
  update public.moreai_customer_memory_preferences
     set enabled = false, disabled_at = now(), updated_at = now()
   where user_id = p_user_id;
  delete from public.moreai_customer_memories where user_id = p_user_id;
  get diagnostics v_deleted = row_count;
