$function$

CREATE OR REPLACE FUNCTION public.moreai_workspace_restore_deleted_file(p_run_id uuid, p_worker_id text, p_user_id uuid, p_workspace_id uuid, p_path text, p_expected_version bigint, p_storage_path text, p_sha256 text, p_size_bytes bigint, p_bucket text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.agent_runs%rowtype; f public.agent_workspace_files%rowtype; v_expected_storage_path text;
begin
  if p_run_id is null or p_worker_id is null or length(p_worker_id) not between 8 and 128
     or p_user_id is null or p_workspace_id is null
     or p_path is null or length(p_path) not between 1 and 512
     or position(chr(92) in p_path)>0 or p_path ~ '(^/|//|(^|/)\.\.?(/|$))'
     or p_path !~ '^[A-Za-z0-9._ -]+(/[A-Za-z0-9._ -]+)*$'
     or p_expected_version is null or p_expected_version<1
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_size_bytes is null or p_size_bytes not between 0 and 2000000
     or p_bucket is null or length(p_bucket) not between 1 and 100 then
    raise exception 'workspace_restore_deleted_arguments_invalid' using errcode='22023';
  end if;
  select * into r from public.agent_runs where id=p_run_id for update;
  if not found or r.user_id<>p_user_id or r.workspace_id is distinct from p_workspace_id
     or r.status<>'running' or r.lease_owner is distinct from p_worker_id
     or r.lease_expires_at is null or r.lease_expires_at<=now() then
    raise exception 'workspace_run_scope_or_lease_invalid' using errcode='42501';
  end if;
  if not exists(select 1 from public.workspaces w where w.id=p_workspace_id and w.status='active'
    and (w.owner_user_id=p_user_id or exists(select 1 from public.workspace_members m
      where m.workspace_id=w.id and m.user_id=p_user_id and m.status='active'))) then
    raise exception 'workspace_membership_required' using errcode='42501';
  end if;
  select * into f from public.agent_workspace_files
    where workspace_id=p_workspace_id and path=p_path and deleted_at is not null for update;
  if not found then raise exception 'workspace_deleted_file_not_found' using errcode='P0002'; end if;
  if f.user_id<>p_user_id then raise exception 'workspace_file_owner_mismatch' using errcode='42501'; end if;
  if f.version<>p_expected_version then raise exception 'workspace_version_conflict' using errcode='40001'; end if;
  if f.pending_token is not null or f.storage_path is null or f.sha256 is null or f.size_bytes is null then
    raise exception 'workspace_file_not_committed_or_write_in_progress' using errcode='40001';
  end if;
  if p_sha256 is distinct from f.sha256 or p_size_bytes is distinct from f.size_bytes then
    raise exception 'workspace_restore_integrity_mismatch' using errcode='22000';
  end if;
  v_expected_storage_path:=p_user_id::text||'/workspaces/'||p_workspace_id::text
    ||'/versions/'||(p_expected_version+1)::text||'/'||p_path;
  if p_storage_path is distinct from v_expected_storage_path then
    raise exception 'workspace_restore_storage_path_invalid' using errcode='22023';
  end if;
  if not exists(select 1 from storage.buckets b where b.id=p_bucket and b.public=false)
     or not exists(select 1 from storage.objects o where o.bucket_id=p_bucket and o.name=p_storage_path) then
    raise exception 'workspace_restore_object_missing_or_bucket_not_private' using errcode='P0002';
  end if;
  update public.agent_workspace_files
    set deleted_at=null,version=version+1,storage_path=p_storage_path,sha256=p_sha256,
        size_bytes=p_size_bytes,updated_at=now()
    where id=f.id and version=p_expected_version and deleted_at is not null and pending_token is null
    returning * into f;
  if not found then raise exception 'workspace_restore_fence_lost' using errcode='40001'; end if;
  return jsonb_build_object('workspace_id',p_workspace_id,'path',f.path,'version',f.version,
    'restored',true,'storage_path',f.storage_path,'sha256',f.sha256,'size_bytes',f.size_bytes);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_customer_workspace_restore_file(p_user_id uuid, p_workspace_id uuid, p_file_id uuid, p_expected_version bigint, p_storage_path text, p_sha256 text, p_size_bytes bigint, p_bucket text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_file public.agent_workspace_files%rowtype; v_expected_storage_path text;
begin
  if p_user_id is null or p_workspace_id is null or p_file_id is null
     or p_expected_version is null or p_expected_version<1
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_size_bytes is null or p_size_bytes not between 0 and 2000000
     or p_bucket is null or length(p_bucket) not between 1 and 100 then
    raise exception 'workspace_file_restore_arguments_invalid' using errcode='22023';
  end if;
  if not exists(select 1 from public.workspaces w where w.id=p_workspace_id and w.status='active'
    and (w.owner_user_id=p_user_id or exists(select 1 from public.workspace_members m
      where m.workspace_id=w.id and m.user_id=p_user_id and m.status='active'))) then
    raise exception 'workspace_membership_required' using errcode='42501';
  end if;
  select * into v_file from public.agent_workspace_files where id=p_file_id and workspace_id=p_workspace_id for update;
  if not found then raise exception 'workspace_file_not_found' using errcode='P0002'; end if;
  if v_file.version<>p_expected_version then raise exception 'workspace_version_conflict' using errcode='40001'; end if;
  if v_file.deleted_at is null then raise exception 'workspace_file_not_deleted' using errcode='22023'; end if;
  if v_file.pending_token is not null or v_file.storage_path is null or v_file.sha256 is null or v_file.size_bytes is null then
    raise exception 'workspace_file_not_committed_or_write_in_progress' using errcode='40001';
  end if;
  if p_sha256 is distinct from v_file.sha256 or p_size_bytes is distinct from v_file.size_bytes then
    raise exception 'workspace_restore_integrity_mismatch' using errcode='22000';
  end if;
  v_expected_storage_path:=v_file.user_id::text||'/workspaces/'||p_workspace_id::text
    ||'/versions/'||(p_expected_version+1)::text||'/'||v_file.path;
  if p_storage_path is distinct from v_expected_storage_path then raise exception 'workspace_restore_storage_path_invalid' using errcode='22023'; end if;
  if not exists(select 1 from storage.buckets b where b.id=p_bucket and b.public=false)
     or not exists(select 1 from storage.objects o where o.bucket_id=p_bucket and o.name=p_storage_path) then
    raise exception 'workspace_restore_object_missing_or_bucket_not_private' using errcode='P0002';
  end if;
  update public.agent_workspace_files set deleted_at=null,version=version+1,storage_path=p_storage_path,
    sha256=p_sha256,size_bytes=p_size_bytes,updated_at=now()
    where id=p_file_id and workspace_id=p_workspace_id and version=p_expected_version
      and deleted_at is not null and pending_token is null returning * into v_file;
  if not found then raise exception 'workspace_file_restore_fence_lost' using errcode='40001'; end if;
  return jsonb_build_object('id',v_file.id,'workspace_id',v_file.workspace_id,'path',v_file.path,
    'version',v_file.version,'deleted_at',v_file.deleted_at,'status','restored',
    'storage_path',v_file.storage_path,'sha256',v_file.sha256,'size_bytes',v_file.size_bytes);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_enqueue_chat_run_with_config(p_user_id uuid, p_conversation_id uuid, p_content text, p_agent_key text, p_idempotency_key text, p_agent_config_id uuid, p_attachment_ids uuid[] DEFAULT '{}'::uuid[], p_skill_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
    v_skill_ids uuid[];
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key is null or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_id is null or coalesce(cardinality(p_attachment_ids),0) > 10
       or coalesce(cardinality(p_skill_ids),0) > 10 then
        raise exception 'invalid_configured_chat_enqueue_request' using errcode = '22023';
    end if;
    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent_configuration_not_found_or_runtime_mismatch' using errcode = '42501';
    end if;
    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
        raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
    end if;
    select coalesce(array_agg(x order by x), '{}'::uuid[]) into v_skill_ids
      from (select distinct unnest(coalesce(p_skill_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_skill_ids) <> coalesce(cardinality(p_skill_ids),0) then
        raise exception 'duplicate_skill_id' using errcode = '22023';
    end if;
    if cardinality(v_skill_ids) > 0 and (
        select count(*) from public.moreai_skill_packages p
        join public.moreai_skill_installs i on i.skill_package_id=p.id and i.owner_user_id=p_user_id
        where p.id = any(v_skill_ids) and p.owner_user_id=p_user_id
          and p.validation_status='validated' and p.license_status='approved' and p.publication_status='published'
          and i.status='installed' and i.permission_status='approved' and i.execution_enabled=true
    ) <> cardinality(v_skill_ids) then
        raise exception 'selected_skill_not_authorized' using errcode = '42501';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;
    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config'->>'id' is distinct from p_agent_config_id::text
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids)
           or coalesce(v_run.input->'skill_ids','[]'::jsonb) is distinct from to_jsonb(v_skill_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;
    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),'skill_ids',to_jsonb(v_skill_ids),
            'agent_config',jsonb_build_object(
                'id',v_config.id,'runtime_key',v_config.runtime_key,'name',v_config.name,
                'system_prompt',v_config.system_prompt,'tool_keys',to_jsonb(v_config.tool_keys),
                'version',v_config.version
            )
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_append_approval_lifecycle_event(p_run_id uuid, p_event_key text, p_event_type text, p_payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.outbox_events;
  v_sequence bigint;
  v_event_id uuid := gen_random_uuid();
  v_created_at timestamptz := now();
begin
  if p_run_id is null or p_event_key is null or char_length(p_event_key) not between 1 and 200
     or p_event_type is null or p_event_type !~ '^[a-z][a-z0-9_.-]{0,79}$'
     or jsonb_typeof(coalesce(p_payload,'{}'::jsonb)) <> 'object'
     or octet_length(coalesce(p_payload,'{}'::jsonb)::text) > 16384 then
    raise exception 'invalid_approval_lifecycle_event' using errcode='22023';
  end if;

  select * into v_existing
    from public.outbox_events
   where aggregate_type='agent_run' and aggregate_id=p_run_id and event_key=p_event_key;
  if found then
    if v_existing.payload->>'event_type' <> p_event_type
       or v_existing.payload->'event_payload' <> coalesce(p_payload,'{}'::jsonb) then
      raise exception 'approval_event_idempotency_conflict' using errcode='22023';
    end if;
    return v_existing.run_sequence;
  end if;

  insert into public.agent_run_event_counters(run_id,last_sequence)
  values(p_run_id,coalesce((select max(sequence) from public.agent_run_events where run_id=p_run_id),0))
  on conflict(run_id) do nothing;
  perform 1 from public.agent_run_event_counters where run_id=p_run_id for update;

  -- Re-check after taking the per-run counter lock to serialize concurrent
  -- decision requests and preserve the existing unique event-key invariant.
  select * into v_existing
    from public.outbox_events
   where aggregate_type='agent_run' and aggregate_id=p_run_id and event_key=p_event_key;
  if found then
    if v_existing.payload->>'event_type' <> p_event_type
       or v_existing.payload->'event_payload' <> coalesce(p_payload,'{}'::jsonb) then
      raise exception 'approval_event_idempotency_conflict' using errcode='22023';
    end if;
    return v_existing.run_sequence;
  end if;

  update public.agent_run_event_counters
     set last_sequence=last_sequence+1,updated_at=v_created_at
   where run_id=p_run_id returning last_sequence into v_sequence;

  insert into public.agent_run_events(id,run_id,event_type,sequence,payload,created_at)
  values(v_event_id,p_run_id,p_event_type,v_sequence,coalesce(p_payload,'{}'::jsonb),v_created_at);

  insert into public.outbox_events(
    id,aggregate_type,aggregate_id,event_type,payload,status,attempts,available_at,
    created_at,event_key,run_sequence
  ) values(
    v_event_id,'agent_run',p_run_id,'run.event',
    jsonb_build_object(
      'run_id',p_run_id,'event_id',v_event_id,'sequence',v_sequence,
      'event_type',p_event_type,'event_payload',coalesce(p_payload,'{}'::jsonb),
      'created_at',v_created_at
    ),
    'pending',0,v_created_at,v_created_at,p_event_key,v_sequence
  );
  return v_sequence;
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_decide_tool_approval(p_approval_id uuid, p_user_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a public.agent_tool_approvals%rowtype;
  p public.agent_run_approval_pauses%rowtype;
  v_status text;
  v_run_status text;
  v_event_type text;
  v_event_payload jsonb;
begin
  if p_decision not in ('approved','denied') then
    raise exception 'invalid_approval_decision' using errcode='22023';
  end if;

  select * into a
    from public.agent_tool_approvals
   where id=p_approval_id and user_id=p_user_id
   for update;
  if not found then
    raise exception 'approval_not_found' using errcode='P0002';
  end if;

  select * into p
    from public.agent_run_approval_pauses
   where approval_id=p_approval_id
   for update;

  if not found then
    if a.status in ('approved','denied','expired','consumed') then
      v_status:=a.status;
    else
      update public.agent_tool_approvals
         set status=case when expires_at<=now() then 'expired' else p_decision end,
             decided_at=now(),decided_by=p_user_id
       where id=p_approval_id
       returning * into a;
      v_status:=a.status;
    end if;

    v_event_type:=case v_status
      when 'approved' then 'tool.approval_granted'
      when 'denied' then 'tool.approval_denied'
      when 'expired' then 'tool.approval_expired'
      else null end;
    if v_event_type is not null then
      v_event_payload:=jsonb_build_object(
        'approval_id',a.id,'tool',a.tool_key,'status',v_status,
        'arguments_hash',a.arguments_hash,'decided_at',a.decided_at
      );
      perform public.moreai_append_approval_lifecycle_event(
        a.run_id,'approval.decision:'||a.id::text||':'||v_status,
        v_event_type,v_event_payload
      );
    end if;

    return jsonb_build_object(
      'id',a.id,'run_id',a.run_id,'status',v_status,'resumed',false
    );
  end if;

  if a.status='pending' then
    v_status:=case when a.expires_at<=now() then 'expired' else p_decision end;
    update public.agent_tool_approvals
       set status=v_status,decided_at=now(),decided_by=p_user_id
     where id=a.id
     returning * into a;
    update public.agent_run_approval_pauses
       set status=v_status,decided_at=now()
     where id=p.id
     returning * into p;
  else
    v_status:=a.status;
    if p.status<>v_status then
      raise exception 'approval_pause_state_conflict' using errcode='40001';
    end if;
  end if;

  v_event_type:=case v_status
    when 'approved' then 'tool.approval_granted'
    when 'denied' then 'tool.approval_denied'
    when 'expired' then 'tool.approval_expired'
    else null end;
  if v_event_type is not null then
    v_event_payload:=jsonb_build_object(
      'approval_id',a.id,'tool',a.tool_key,'status',v_status,
      'arguments_hash',a.arguments_hash,'decided_at',a.decided_at,
      'checkpoint_key',p.checkpoint_key
    );
    perform public.moreai_append_approval_lifecycle_event(
      a.run_id,'approval.decision:'||a.id::text||':'||v_status,
      v_event_type,v_event_payload
    );
  end if;

  update public.agent_runs
     set status='queued',resume_pending=true,available_at=now(),updated_at=now()
   where id=p.run_id and status='waiting_approval'
   returning status into v_run_status;

  update public.agent_run_checkpoints
     set state=state||jsonb_build_object(
       'status',v_status,'decided_at',a.decided_at,'resume_pending',true
     ),created_at=now()
   where run_id=p.run_id and checkpoint_key=p.checkpoint_key;

  if coalesce(v_run_status='queued',false) then
    perform public.moreai_append_approval_lifecycle_event(
      p.run_id,'approval.resume_queued:'||a.id::text,
      'run.resume_queued',
      jsonb_build_object(
        'approval_id',a.id,'status',v_status,
        'checkpoint_key',p.checkpoint_key,'resume_pending',true
      )
    );
  end if;

  return jsonb_build_object(
    'id',a.id,'run_id',a.run_id,'status',v_status,
    'resumed',coalesce(v_run_status='queued',false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_customer_set_memory_consent(p_user_id uuid, p_enabled boolean, p_consent_version text)
 RETURNS moreai_customer_memory_preferences
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_row public.moreai_customer_memory_preferences%rowtype;
begin
  if p_user_id is null or p_enabled is null or p_consent_version is null
     or length(p_consent_version) not between 1 and 40 then
    raise exception 'memory_consent_arguments_invalid' using errcode = '22023';
  end if;
  insert into public.moreai_customer_memory_preferences (
    user_id, enabled, consent_version, consented_at, disabled_at, updated_at
  ) values (
    p_user_id, p_enabled, p_consent_version,
    case when p_enabled then now() else null end,
    case when p_enabled then null else now() end,
    now()
  )
  on conflict (user_id) do update set
    enabled = excluded.enabled,
    consent_version = excluded.consent_version,
    consented_at = case when excluded.enabled then now()
                        else public.moreai_customer_memory_preferences.consented_at end,
    disabled_at = case when excluded.enabled then null else now() end,
    updated_at = now()
  returning * into v_row;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_worker_purge_expired_customer_memories()
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_deleted bigint;
begin
  delete from public.moreai_customer_memories
   where expires_at <= now();
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_worker_publish_capabilities(p_worker_id text, p_runtime_keys text[], p_capabilities jsonb, p_status text DEFAULT 'healthy'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_row public.moreai_worker_capability_snapshots%rowtype;
begin
    if p_worker_id is null or length(p_worker_id) < 8 or length(p_worker_id) > 128
       or p_runtime_keys is null or p_capabilities is null
       or jsonb_typeof(p_capabilities) <> 'object'
       or p_status not in ('healthy', 'degraded') then
        raise exception 'invalid worker capability heartbeat' using errcode = '22023';
    end if;
    insert into public.moreai_worker_capability_snapshots(
        worker_id, runtime_keys, capabilities, status, last_seen_at, updated_at
    ) values (
        p_worker_id, p_runtime_keys, p_capabilities, p_status, now(), now()
    )
    on conflict (worker_id) do update set
        runtime_keys = excluded.runtime_keys,
        capabilities = excluded.capabilities,
        status = excluded.status,
        last_seen_at = now(),
        updated_at = now()
    returning * into v_row;
    return jsonb_build_object(
        'worker_id', v_row.worker_id,
        'runtime_keys', to_jsonb(v_row.runtime_keys),
        'status', v_row.status,
        'last_seen_at', v_row.last_seen_at
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_enqueue_chat_run_with_config_snapshot(p_user_id uuid, p_source_run_id uuid, p_conversation_id uuid, p_content text, p_agent_key text, p_idempotency_key text, p_agent_config_snapshot jsonb, p_attachment_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_source_run public.agent_runs%rowtype;
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
begin
    if p_user_id is null or p_source_run_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_snapshot is null or jsonb_typeof(p_agent_config_snapshot) <> 'object'
       or p_agent_config_snapshot->>'runtime_key' is distinct from p_agent_key
       or jsonb_typeof(p_agent_config_snapshot->'tool_keys') <> 'array'
       or coalesce(cardinality(p_attachment_ids),0) > 10 then
        raise exception 'invalid_saved_agent_retry_request' using errcode = '22023';
    end if;
    select * into v_source_run from public.agent_runs
     where id = p_source_run_id and user_id = p_user_id for share;
    if not found
       or v_source_run.status not in ('failed','timed_out','expired')
       or v_source_run.conversation_id is distinct from p_conversation_id
       or v_source_run.input->>'prompt' is distinct from p_content
       or v_source_run.input->>'agent_key' is distinct from p_agent_key
       or v_source_run.input->'agent_config' is distinct from p_agent_config_snapshot then
        raise exception 'saved_agent_retry_source_mismatch' using errcode = '42501';
    end if;
    if exists (
        select 1 from public.agent_run_events e
         where e.run_id = p_source_run_id
           and e.event_type like 'tool.%'
           and coalesce(e.payload->>'tool','') not in (
               'create_chat_completion','knowledge_search','google_search',
               'planning','workspace_read_file','terminate'
           )
    ) then
        raise exception 'saved_agent_retry_has_side_effects' using errcode = '22023';
    end if;
    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0)
       or coalesce(v_source_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
        raise exception 'saved_agent_retry_attachment_mismatch' using errcode = '22023';
    end if;
    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;
    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;
    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config' is distinct from p_agent_config_snapshot
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;
    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
            'agent_config',p_agent_config_snapshot,'retry_of_run_id',p_source_run_id
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_learning_progress_update(p_user_id uuid, p_run_id uuid, p_lesson_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 v_lesson public.learning_lessons%rowtype;
 v_progress public.learning_progress%rowtype;
 v_total integer;
 v_completed integer;
 v_percent numeric(5,2);
 v_path_status text;
begin
 if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then
  raise exception 'learning_run_owner_mismatch' using errcode='42501';
 end if;
 if p_status <> 'in_progress' then
  raise exception 'learning_progress_completion_is_assessment_derived' using errcode='22023';
 end if;
 select * into v_lesson from public.learning_lessons where id=p_lesson_id and owner_user_id=p_user_id;
 if not found then raise exception 'learning_lesson_not_found' using errcode='P0002'; end if;

 insert into public.learning_enrollments(path_id,user_id,status)
 values(v_lesson.path_id,p_user_id,'active')
 on conflict(path_id,user_id) do update set
  status=case when public.learning_enrollments.status='completed' then 'completed' else 'active' end,
  updated_at=now();

 insert into public.learning_progress(
  user_id,path_id,module_id,lesson_id,status,progress_percent,last_run_id,started_at,completed_at,updated_at
 ) values(p_user_id,v_lesson.path_id,v_lesson.module_id,v_lesson.id,'in_progress',1,p_run_id,now(),null,now())
 on conflict(user_id,lesson_id) do update set
  status=case when public.learning_progress.status='completed' then 'completed' else 'in_progress' end,
  progress_percent=case when public.learning_progress.status='completed' then 100 else greatest(public.learning_progress.progress_percent,1) end,
  last_run_id=excluded.last_run_id,
  started_at=coalesce(public.learning_progress.started_at,now()),
  completed_at=case when public.learning_progress.status='completed' then public.learning_progress.completed_at else null end,
  updated_at=now()
 returning * into v_progress;

 select count(*),count(*) filter(where p.status='completed')
 into v_total,v_completed
 from public.learning_lessons l
 left join public.learning_progress p on p.lesson_id=l.id and p.user_id=p_user_id
 where l.path_id=v_lesson.path_id and l.owner_user_id=p_user_id;
 v_percent := case when v_total=0 then 0 else round((v_completed::numeric/v_total::numeric)*100,2) end;
 v_path_status := case when v_total>0 and v_completed=v_total then 'completed' else 'active' end;

 update public.learning_enrollments set
  status=case when v_path_status='completed' then 'completed' else 'active' end,
  completed_at=case when v_path_status='completed' then coalesce(completed_at,now()) else null end,
  updated_at=now()
 where path_id=v_lesson.path_id and user_id=p_user_id;
 update public.learning_paths set status=v_path_status,updated_at=now()
 where id=v_lesson.path_id and owner_user_id=p_user_id;

 insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
 values(p_user_id,p_run_id,'progress',v_progress.id,jsonb_build_object(
  'lesson_id',v_lesson.id,'status',v_progress.status,'progress_percent',v_progress.progress_percent,
  'path_progress_percent',v_percent,'completed_lessons',v_completed,'total_lessons',v_total
 ))
 on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;

 return jsonb_build_object(
  'progress_id',v_progress.id,'lesson_id',v_lesson.id,'status',v_progress.status,
  'progress_percent',v_progress.progress_percent,'path_status',v_path_status,
  'path_progress_percent',v_percent,'completed_lessons',v_completed,'total_lessons',v_total
 );
end $function$

CREATE OR REPLACE FUNCTION public.moreai_learning_path_create(p_user_id uuid, p_run_id uuid, p_title text, p_description text, p_education_level text, p_learning_goal text, p_modules jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_path public.learning_paths%rowtype;
  v_module jsonb;
  v_lesson jsonb;
  v_module_row public.learning_modules%rowtype;
  v_module_index integer := 0;
  v_lesson_index integer;
  v_count integer := 0;
begin
  if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then
    raise exception 'learning_run_owner_mismatch' using errcode='42501';
  end if;
  if jsonb_typeof(p_modules) is distinct from 'array' then
    raise exception 'learning_modules_invalid' using errcode='22023';
  end if;
  if jsonb_array_length(p_modules) not between 1 and 30 then
    raise exception 'learning_modules_invalid' using errcode='22023';
  end if;
  select * into v_path from public.learning_paths where created_by_run_id=p_run_id and owner_user_id=p_user_id;
  if found then
    select count(*) into v_module_index from public.learning_modules where path_id=v_path.id;
    select count(*) into v_count from public.learning_lessons where path_id=v_path.id;
    return jsonb_build_object('path_id',v_path.id,'title',v_path.title,'module_count',v_module_index,'lesson_count',v_count,'status',v_path.status,'replayed',true);
  end if;
  insert into public.learning_paths(owner_user_id,created_by_run_id,title,description,education_level,learning_goal,status)
  values(p_user_id,p_run_id,left(btrim(p_title),180),coalesce(p_description,''),coalesce(p_education_level,'self_directed'),coalesce(p_learning_goal,''),'active')
  returning * into v_path;
  for v_module in select value from jsonb_array_elements(p_modules) loop
    if length(btrim(coalesce(v_module->>'title',''))) = 0 then raise exception 'learning_module_title_required' using errcode='22023'; end if;
    insert into public.learning_modules(path_id,owner_user_id,module_index,title,summary,estimated_minutes)
    values(v_path.id,p_user_id,v_module_index,left(btrim(v_module->>'title'),180),coalesce(v_module->>'summary',''),greatest(1,least(10080,coalesce((v_module->>'estimated_minutes')::integer,30))))
    returning * into v_module_row;
    v_lesson_index := 0;
    if jsonb_typeof(v_module->'lessons') = 'array' then
      for v_lesson in select value from jsonb_array_elements(v_module->'lessons') loop
        insert into public.learning_lessons(path_id,module_id,owner_user_id,lesson_index,title,content_md,objectives,source_run_id,status)
        values(v_path.id,v_module_row.id,p_user_id,v_lesson_index,left(btrim(coalesce(v_lesson->>'title','Lesson')),180),coalesce(v_lesson->>'content_md',''),case when jsonb_typeof(v_lesson->'objectives')='array' then v_lesson->'objectives' else '[]'::jsonb end,p_run_id,case when coalesce(v_lesson->>'content_md','')='' then 'outline' else 'ready' end);
        v_lesson_index := v_lesson_index + 1; v_count := v_count + 1;
      end loop;
    end if;
    v_module_index := v_module_index + 1;
  end loop;
  insert into public.learning_enrollments(path_id,user_id,status) values(v_path.id,p_user_id,'active') on conflict(path_id,user_id) do nothing;
  insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
  values(p_user_id,p_run_id,'learning_path',v_path.id,jsonb_build_object('title',v_path.title,'module_count',v_module_index,'lesson_count',v_count))
  on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;
  return jsonb_build_object('path_id',v_path.id,'title',v_path.title,'module_count',v_module_index,'lesson_count',v_count,'status',v_path.status,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.moreai_learning_lesson_generate(p_user_id uuid, p_run_id uuid, p_lesson_id uuid, p_title text, p_content_md text, p_objectives jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_lesson public.learning_lessons%rowtype; v_next integer;
begin
  if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then raise exception 'learning_run_owner_mismatch' using errcode='42501'; end if;
  select * into v_lesson from public.learning_lessons where id=p_lesson_id and owner_user_id=p_user_id for update;
  if not found then raise exception 'learning_lesson_not_found' using errcode='P0002'; end if;
  if v_lesson.status='ready' and v_lesson.source_run_id=p_run_id then
    return jsonb_build_object('lesson_id',v_lesson.id,'content_version',v_lesson.content_version,'status','ready','replayed',true);
  end if;
  v_next := case when btrim(v_lesson.content_md)='' then 1 else v_lesson.content_version + 1 end;
  if btrim(v_lesson.content_md) <> '' then
    insert into public.learning_lesson_versions(lesson_id,owner_user_id,version,content_md,objectives,source_run_id)
    values(v_lesson.id,p_user_id,v_lesson.content_version,v_lesson.content_md,v_lesson.objectives,v_lesson.source_run_id)
    on conflict(lesson_id,version) do nothing;
  end if;
  update public.learning_lessons set title=left(btrim(p_title),180),content_md=p_content_md,
    objectives=case when jsonb_typeof(p_objectives)='array' then p_objectives else '[]'::jsonb end,
    content_version=v_next,status='ready',source_run_id=p_run_id,updated_at=now()
  where id=v_lesson.id;
  insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
  values(p_user_id,p_run_id,'lesson',v_lesson.id,jsonb_build_object('version',v_next,'title',p_title))
  on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;
  return jsonb_build_object('lesson_id',v_lesson.id,'content_version',v_next,'status','ready','replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.moreai_learning_quiz_generate(p_user_id uuid, p_run_id uuid, p_lesson_id uuid, p_title text, p_questions jsonb, p_pass_score numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_lesson public.learning_lessons%rowtype; v_quiz public.learning_quizzes%rowtype;
begin
  if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then raise exception 'learning_run_owner_mismatch' using errcode='42501'; end if;
  select * into v_lesson from public.learning_lessons where id=p_lesson_id and owner_user_id=p_user_id;
  if not found then raise exception 'learning_lesson_not_found' using errcode='P0002'; end if;
  if jsonb_typeof(p_questions) is distinct from 'array' then raise exception 'learning_questions_invalid' using errcode='22023'; end if;
  if jsonb_array_length(p_questions) not between 1 and 100 then raise exception 'learning_questions_invalid' using errcode='22023'; end if;
  select * into v_quiz from public.learning_quizzes where source_run_id=p_run_id and lesson_id=p_lesson_id and owner_user_id=p_user_id;
  if found then return jsonb_build_object('quiz_id',v_quiz.id,'lesson_id',v_lesson.id,'question_count',jsonb_array_length(v_quiz.questions),'replayed',true); end if;
  insert into public.learning_quizzes(path_id,lesson_id,owner_user_id,title,questions,pass_score,source_run_id)
  values(v_lesson.path_id,v_lesson.id,p_user_id,left(btrim(p_title),180),p_questions,greatest(0,least(100,coalesce(p_pass_score,70))),p_run_id)
  returning * into v_quiz;
  insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
  values(p_user_id,p_run_id,'quiz',v_quiz.id,jsonb_build_object('lesson_id',v_lesson.id,'question_count',jsonb_array_length(p_questions)))
  on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;
  return jsonb_build_object('quiz_id',v_quiz.id,'lesson_id',v_lesson.id,'question_count',jsonb_array_length(p_questions),'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.moreai_enqueue_chat_run_with_attachments(p_user_id uuid, p_conversation_id uuid, p_content text, p_agent_key text, p_idempotency_key text, p_attachment_ids uuid[] DEFAULT '{}'::uuid[], p_skill_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_conversation public.conversations%rowtype;
  v_message public.conversation_messages%rowtype;
  v_run public.agent_runs%rowtype;
  v_attachment_ids uuid[];
  v_attachment_count integer;
  v_skill_ids uuid[];
begin
  if p_user_id is null or p_conversation_id is null
     or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
     or p_agent_key is null or p_agent_key not in ('manus','planning','toolcall')
     or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
     or coalesce(cardinality(p_attachment_ids),0) > 10
     or coalesce(cardinality(p_skill_ids),0) > 10 then
    raise exception 'invalid_chat_enqueue_request' using errcode = '22023';
  end if;

  select coalesce(array_agg(x order by x), '{}'::uuid[])
    into v_attachment_ids
    from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
  if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
    raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
  end if;

  select coalesce(array_agg(x order by x), '{}'::uuid[]) into v_skill_ids
    from (select distinct unnest(coalesce(p_skill_ids, '{}'::uuid[])) as x) q;
  if cardinality(v_skill_ids) <> coalesce(cardinality(p_skill_ids),0) then
    raise exception 'duplicate_skill_id' using errcode = '22023';
  end if;
  if cardinality(v_skill_ids) > 0 and (
    select count(*) from public.moreai_skill_packages p
    join public.moreai_skill_installs i on i.skill_package_id=p.id and i.owner_user_id=p_user_id
    where p.id = any(v_skill_ids) and p.owner_user_id=p_user_id
      and p.validation_status='validated' and p.license_status='approved' and p.publication_status='published'
      and i.status='installed' and i.permission_status='approved' and i.execution_enabled=true
  ) <> cardinality(v_skill_ids) then
    raise exception 'selected_skill_not_authorized' using errcode = '42501';
  end if;
  select * into v_conversation
    from public.conversations
   where id = p_conversation_id and user_id = p_user_id and status = 'active'
   for update;
  if not found then
    raise exception 'conversation_not_found_or_inactive' using errcode = '42501';
  end if;

  if cardinality(v_attachment_ids) > 0 then
    select count(*) into v_attachment_count
      from public.artifacts a
     where a.id = any(v_attachment_ids)
       and a.user_id = p_user_id
       and a.metadata->>'purpose' = 'chat_attachment'
       and a.metadata->>'conversation_id' = p_conversation_id::text
       and a.size_bytes between 1 and 2000000
       and a.mime_type in (
         'text/plain','text/markdown','text/csv','application/json',
         'application/pdf','image/jpeg','image/png','image/webp'
       );
    if v_attachment_count <> cardinality(v_attachment_ids) then
      raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
    end if;
  end if;

  select * into v_run
    from public.agent_runs
   where user_id = p_user_id and idempotency_key = p_idempotency_key;
  if found then
    if v_run.input->>'prompt' is distinct from p_content
       or v_run.input->>'agent_key' is distinct from p_agent_key
       or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids)
       or coalesce(v_run.input->'skill_ids','[]'::jsonb) is distinct from to_jsonb(v_skill_ids) then
      raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
    end if;
    return pg_catalog.jsonb_build_object('run',pg_catalog.to_jsonb(v_run),'message',null,'replayed',true);
  end if;

  insert into public.conversation_messages (conversation_id,user_id,role,content,metadata)
  values (p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb)
  returning * into v_message;

  insert into public.agent_runs (
    user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts
  ) values (
    p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
    pg_catalog.jsonb_build_object(
      'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
      'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
      'skill_ids',to_jsonb(v_skill_ids)
    ),3
  ) returning * into v_run;

  update public.conversation_messages
     set run_id = v_run.id
   where id = v_message.id and user_id = p_user_id;
  v_message.run_id := v_run.id;

  if cardinality(v_attachment_ids) > 0 then
    insert into public.conversation_message_attachments (
      user_id,conversation_id,message_id,run_id,artifact_id
    )
    select p_user_id,p_conversation_id,v_message.id,v_run.id,x
      from unnest(v_attachment_ids) as x;
  end if;

  return pg_catalog.jsonb_build_object('run',pg_catalog.to_jsonb(v_run),'message',pg_catalog.to_jsonb(v_message),'replayed',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_learning_answer_assess(p_user_id uuid, p_run_id uuid, p_quiz_id uuid, p_answers jsonb, p_score numeric, p_feedback jsonb, p_rubric jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 v_quiz public.learning_quizzes%rowtype;
 v_attempt public.learning_quiz_attempts%rowtype;
 v_assessment public.learning_assessments%rowtype;
 v_all_passed boolean := false;
 v_progress public.learning_progress%rowtype;
 v_total integer := 0;
 v_completed integer := 0;
 v_remaining integer := 0;
 v_path_percent numeric(5,2) := 0;
begin
 if not exists(select 1 from public.agent_runs r where r.id=p_run_id and r.user_id=p_user_id) then
  raise exception 'learning_run_owner_mismatch' using errcode='42501';
 end if;
 select * into v_quiz from public.learning_quizzes where id=p_quiz_id and owner_user_id=p_user_id;
 if not found then raise exception 'learning_quiz_not_found' using errcode='P0002'; end if;
 if jsonb_typeof(p_answers) is distinct from 'array' then
  raise exception 'learning_answers_invalid' using errcode='22023';
 end if;

 insert into public.learning_quiz_attempts(quiz_id,user_id,run_id,answers,score,passed,feedback)
 values(v_quiz.id,p_user_id,p_run_id,p_answers,greatest(0,least(100,p_score)),p_score>=v_quiz.pass_score,coalesce(p_feedback,'{}'::jsonb))
 on conflict(run_id,quiz_id) do update set
  answers=excluded.answers,score=excluded.score,passed=excluded.passed,feedback=excluded.feedback
 returning * into v_attempt;

 insert into public.learning_assessments(
  user_id,path_id,module_id,lesson_id,quiz_id,run_id,assessment_type,score,rubric,feedback
 ) values(
  p_user_id,v_quiz.path_id,v_quiz.module_id,v_quiz.lesson_id,v_quiz.id,p_run_id,'quiz',
  v_attempt.score,coalesce(p_rubric,'[]'::jsonb),coalesce(p_feedback,'{}'::jsonb)
 )
 on conflict(run_id,quiz_id) where quiz_id is not null do update set
  score=excluded.score,rubric=excluded.rubric,feedback=excluded.feedback
 returning * into v_assessment;

 insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
 values(p_user_id,p_run_id,'assessment',v_assessment.id,jsonb_build_object(
  'quiz_id',v_quiz.id,'attempt_id',v_attempt.id,'score',v_attempt.score,'passed',v_attempt.passed
 ))
 on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;

 if v_attempt.passed then
  select not exists(
   select 1 from public.learning_quizzes q
   where q.lesson_id=v_quiz.lesson_id and q.owner_user_id=p_user_id
     and not exists(
      select 1 from public.learning_quiz_attempts a
      where a.quiz_id=q.id and a.user_id=p_user_id and a.passed=true
     )
  ) into v_all_passed;

  if v_all_passed then
   insert into public.learning_progress(
    user_id,path_id,module_id,lesson_id,status,progress_percent,last_run_id,started_at,completed_at,updated_at
   ) values(
    p_user_id,v_quiz.path_id,v_quiz.module_id,v_quiz.lesson_id,'in_progress',1,p_run_id,now(),null,now()
   )
   on conflict(user_id,lesson_id) do update set
    last_run_id=excluded.last_run_id,
    started_at=coalesce(public.learning_progress.started_at,now()),
    updated_at=now()
   returning * into v_progress;

   update public.learning_progress set
    status='completed',progress_percent=100,
    completed_at=coalesce(completed_at,now()),last_run_id=p_run_id,updated_at=now()
   where user_id=p_user_id and lesson_id=v_quiz.lesson_id
   returning * into v_progress;

   insert into public.learning_run_artifacts(user_id,run_id,artifact_type,resource_id,payload)
   values(p_user_id,p_run_id,'progress',v_progress.id,jsonb_build_object(
    'lesson_id',v_quiz.lesson_id,'status','completed','progress_percent',100,
    'completion_source','all_required_quizzes_passed'
   ))
   on conflict(run_id,artifact_type,resource_id) do update set payload=excluded.payload;
  end if;
 end if;

 select count(*),count(*) filter(where p.status='completed')
 into v_total,v_completed
 from public.learning_lessons l
 left join public.learning_progress p on p.lesson_id=l.id and p.user_id=p_user_id
 where l.path_id=v_quiz.path_id and l.owner_user_id=p_user_id;
 v_remaining := greatest(v_total-v_completed,0);
 v_path_percent := case when v_total=0 then 0 else round((v_completed::numeric/v_total::numeric)*100,2) end;
 if v_total>0 and v_remaining=0 then
  update public.learning_enrollments set status='completed',
   completed_at=coalesce(completed_at,now()),updated_at=now()
  where path_id=v_quiz.path_id and user_id=p_user_id;
  update public.learning_paths set status='completed',updated_at=now()
  where id=v_quiz.path_id and owner_user_id=p_user_id;
 end if;

 return jsonb_build_object(
  'attempt_id',v_attempt.id,'assessment_id',v_assessment.id,
  'score',v_attempt.score,'passed',v_attempt.passed,
  'lesson_completed',coalesce(v_progress.status='completed',false),
  'path_progress_percent',v_path_percent,'completed_lessons',v_completed,'total_lessons',v_total
 );
end $function$

CREATE OR REPLACE FUNCTION public.moreai_review_skill_permissions(p_skill_id uuid, p_install_id uuid, p_actor_user_id uuid, p_decision text, p_granted_permissions text[], p_review_note text, p_execution_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_install public.moreai_skill_installs%rowtype;
  v_package public.moreai_skill_packages%rowtype;
  v_requested text[];
begin
  if p_decision not in ('approved','rejected') or p_granted_permissions is null
     or coalesce(cardinality(p_granted_permissions),0)>20 then
    raise exception 'skill_permission_review_payload_invalid' using errcode='22023';
  end if;
  select * into v_install from public.moreai_skill_installs
   where id=p_install_id and skill_package_id=p_skill_id for update;
  if not found then raise exception 'skill_install_not_found' using errcode='P0002'; end if;
  select * into v_package from public.moreai_skill_packages where id=p_skill_id for share;
  if not found then raise exception 'skill_not_found' using errcode='P0002'; end if;
  select coalesce(array_agg(value),'{}'::text[]) into v_requested
    from jsonb_array_elements_text(coalesce(v_install.permission_request,'[]'::jsonb)) as value;
  if p_decision='approved' and not (p_granted_permissions <@ v_requested) then
    raise exception 'granted_permissions_must_be_subset_of_requested' using errcode='22023';
  end if;
  update public.moreai_skill_installs set
    permission_status=p_decision,
    granted_permissions=case when p_decision='approved' then to_jsonb(p_granted_permissions) else '[]'::jsonb end,
    execution_enabled=(p_decision='approved' and p_execution_enabled
      and v_package.validation_status='validated' and v_package.license_status='approved'
      and v_package.publication_status='published'
      and exists(select 1 from public.moreai_skill_source_files sf
        where sf.skill_package_id=p_skill_id and sf.owner_user_id=v_install.owner_user_id)),
    updated_at=now()
  where id=p_install_id returning * into v_install;
  insert into public.moreai_skill_registry_audit(
    skill_package_id,skill_install_id,actor_user_id,owner_user_id,event_type,decision,
    permission_snapshot,event_detail
  ) values(
    p_skill_id,p_install_id,p_actor_user_id,v_install.owner_user_id,'permission_reviewed',
    p_decision,to_jsonb(v_install.granted_permissions),
    jsonb_build_object('review_note',left(coalesce(p_review_note,''),2000),
      'execution_enabled',v_install.execution_enabled,'requested_permissions',to_jsonb(v_requested))
  );
  return jsonb_build_object('install_id',v_install.id,'permission_status',v_install.permission_status,
    'granted_permissions',to_jsonb(v_install.granted_permissions),
    'execution_enabled',v_install.execution_enabled);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_consume_google_oauth_state(p_state_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_state public.moreai_oauth_states%rowtype;
begin
  delete from public.moreai_oauth_states where state_hash=p_state_hash
    and provider='google' and expires_at>now()
    returning * into v_state;
  if not found then raise exception 'oauth_state_invalid_or_expired' using errcode='42501'; end if;
  return jsonb_build_object('user_id',v_state.user_id,'provider',v_state.provider,
    'scopes',v_state.scopes,'pkce_verifier_ciphertext',v_state.pkce_verifier_ciphertext,
    'redirect_uri',v_state.redirect_uri);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_finish_connection_action(p_action_id uuid, p_user_id uuid, p_status text, p_provider_resource_id text, p_result_metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_action public.moreai_connection_actions%rowtype;
begin
 if p_status not in ('completed','unknown','failed') or jsonb_typeof(p_result_metadata)<>'object' then
  raise exception 'connection_action_result_invalid' using errcode='22023';
 end if;
 update public.moreai_connection_actions set status=p_status,
  provider_resource_id=left(p_provider_resource_id,512),result_metadata=p_result_metadata,updated_at=now()
 where id=p_action_id and user_id=p_user_id and status='started'
 returning * into v_action;
 if not found then raise exception 'connection_action_not_pending' using errcode='40001'; end if;
 insert into public.moreai_connection_audit(connection_id,user_id,provider,event_type,scopes,detail)
 values(v_action.connection_id,p_user_id,'google',
  case when p_status='completed' then 'action_completed' when p_status='failed' then 'action_failed' else 'action_requested' end,
  '[]'::jsonb,jsonb_build_object('action_id',v_action.id,'action_type',v_action.action_type,'status',p_status));
 return jsonb_build_object('action_id',v_action.id,'status',v_action.status,'provider_resource_id',v_action.provider_resource_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_enqueue_chat_run_with_config(p_user_id uuid, p_conversation_id uuid, p_content text, p_agent_key text, p_idempotency_key text, p_agent_config_id uuid, p_attachment_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_conversation public.conversations%rowtype;
    v_message public.conversation_messages%rowtype;
    v_run public.agent_runs%rowtype;
    v_config public.moreai_customer_agent_configs%rowtype;
    v_attachment_ids uuid[];
    v_attachment_count integer;
    v_agent_config_snapshot jsonb;
begin
    if p_user_id is null or p_conversation_id is null
       or p_content is null or length(btrim(p_content)) = 0 or length(p_content) > 100000
       or p_agent_key is null or p_agent_key not in ('manus','toolcall')
       or p_idempotency_key is null or length(p_idempotency_key) not between 12 and 128
       or p_agent_config_id is null or coalesce(cardinality(p_attachment_ids),0) > 10 then
        raise exception 'invalid_configured_chat_enqueue_request' using errcode = '22023';
    end if;

    select * into v_config from public.moreai_customer_agent_configs
     where id = p_agent_config_id and user_id = p_user_id and enabled = true for share;
    if not found or v_config.runtime_key <> p_agent_key then
        raise exception 'agent_configuration_not_found_or_runtime_mismatch' using errcode = '42501';
    end if;
    if v_config.preferred_model_id is not null and not exists (
        select 1 from public.llm_models m
        join public.llm_providers p on p.id = m.provider_id
        where m.id = v_config.preferred_model_id and m.enabled = true and p.enabled = true
    ) then
        raise exception 'configured_model_is_not_enabled' using errcode = '22023';
    end if;

    v_agent_config_snapshot := jsonb_build_object(
        'id', v_config.id,
        'runtime_key', v_config.runtime_key,
        'name', v_config.name,
        'system_prompt', v_config.system_prompt,
        'tool_keys', to_jsonb(v_config.tool_keys),
        'preferred_model_id', v_config.preferred_model_id,
        'version', v_config.version
    );

    select coalesce(array_agg(x order by x), '{}'::uuid[])
      into v_attachment_ids
      from (select distinct unnest(coalesce(p_attachment_ids, '{}'::uuid[])) as x) q;
    if cardinality(v_attachment_ids) <> coalesce(cardinality(p_attachment_ids),0) then
        raise exception 'duplicate_chat_attachment_id' using errcode = '22023';
    end if;

    select * into v_conversation from public.conversations
     where id = p_conversation_id and user_id = p_user_id and status = 'active' for update;
    if not found then raise exception 'conversation_not_found_or_inactive' using errcode = '42501'; end if;

    if cardinality(v_attachment_ids) > 0 then
        select count(*) into v_attachment_count from public.artifacts a
         where a.id = any(v_attachment_ids)
           and a.user_id = p_user_id
           and a.metadata->>'purpose' = 'chat_attachment'
           and a.metadata->>'conversation_id' = p_conversation_id::text
           and a.size_bytes between 1 and 2000000
           and a.mime_type in ('text/plain','text/markdown','text/csv','application/json',
             'application/pdf','image/jpeg','image/png','image/webp');
        if v_attachment_count <> cardinality(v_attachment_ids) then
            raise exception 'chat_attachment_not_owned_or_not_available' using errcode = '42501';
        end if;
    end if;

    select * into v_run from public.agent_runs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
        if v_run.input->>'prompt' is distinct from p_content
           or v_run.input->>'agent_key' is distinct from p_agent_key
           or v_run.input->'agent_config' is distinct from v_agent_config_snapshot
           or coalesce(v_run.input->'attachment_ids','[]'::jsonb) is distinct from to_jsonb(v_attachment_ids) then
            raise exception 'chat_idempotency_key_payload_conflict' using errcode = '22023';
        end if;
        return jsonb_build_object('run',to_jsonb(v_run),'message',null,'replayed',true);
    end if;

    insert into public.conversation_messages(conversation_id,user_id,role,content,metadata)
    values(p_conversation_id,p_user_id,'user',p_content,'{}'::jsonb) returning * into v_message;
    insert into public.agent_runs(user_id,workspace_id,conversation_id,status,idempotency_key,input,max_attempts)
    values(
        p_user_id,v_conversation.workspace_id,p_conversation_id,'queued',p_idempotency_key,
        jsonb_build_object(
            'prompt',p_content,'agent_key',p_agent_key,'conversation_id',p_conversation_id,
            'message_id',v_message.id,'attachment_ids',to_jsonb(v_attachment_ids),
            'agent_config',v_agent_config_snapshot
        ),3
    ) returning * into v_run;
    update public.conversation_messages set run_id = v_run.id
     where id = v_message.id and user_id = p_user_id;
    v_message.run_id := v_run.id;
    if cardinality(v_attachment_ids) > 0 then
        insert into public.conversation_message_attachments(user_id,conversation_id,message_id,run_id,artifact_id)
        select p_user_id,p_conversation_id,v_message.id,v_run.id,x from unnest(v_attachment_ids) as x;
    end if;
    return jsonb_build_object('run',to_jsonb(v_run),'message',to_jsonb(v_message),'replayed',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_admin_configure_llm_provider(p_actor_user_id uuid, p_provider_id uuid, p_base_url text, p_secret_env_name text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_provider public.llm_providers%rowtype; v_host text;
begin
  if p_actor_user_id is null or p_provider_id is null or p_base_url is null
    or p_base_url !~* '^https://[a-z0-9.-]+(:[0-9]{1,5})?(/[a-z0-9._~!$&''()*+,;=:@%/-]*)?$'
    or p_secret_env_name is null or p_secret_env_name !~ '^MOREAI_PROVIDER_[A-Z0-9_]{1,100}$' then
    raise exception using errcode='22023',message='LLM_PROVIDER_CONFIG_INVALID';
  end if;
  v_host := lower(split_part(split_part(p_base_url,'://',2),'/',1));
  v_host := split_part(v_host,':',1);
  if v_host in ('localhost','localhost.localdomain')
    or v_host ~ '^(127\.|10\.|192\.168\.|169\.254\.|0\.)'
    or v_host ~ '^172\.(1[6-9]|2[0-9]|3[01])\.' then
    raise exception using errcode='22023',message='LLM_PROVIDER_HOST_NOT_ALLOWED';
  end if;
  if not exists (
    select 1 from public.user_role_assignments ura
    join public.roles r on r.id=ura.role_id
    join public.role_permissions rp on rp.role_id=r.id
    join public.permissions p on p.id=rp.permission_id
    where ura.user_id=p_actor_user_id and ura.scope_type='platform' and ura.scope_id is null
      and (ura.expires_at is null or ura.expires_at>now()) and r.scope='platform'
      and p.key='platform.models.manage'
  ) then raise exception using errcode='42501',message='ADMIN_PERMISSION_DENIED'; end if;
  select * into v_provider from public.llm_providers where id=p_provider_id for update;
  if not found then raise exception using errcode='P0002',message='LLM_PROVIDER_NOT_FOUND'; end if;
  if (v_provider.key='openai' and v_host<>'api.openai.com')
    or (v_provider.key='google' and v_host<>'generativelanguage.googleapis.com')
    or v_provider.key not in ('openai','google') then
    raise exception using errcode='22023',message='LLM_PROVIDER_ENDPOINT_NOT_SUPPORTED_BY_ADAPTER';
  end if;
  update public.llm_providers
  set config=jsonb_build_object('base_url',rtrim(p_base_url,'/'),'secret_env_name',p_secret_env_name),updated_at=now()
  where id=p_provider_id returning * into v_provider;
  insert into public.admin_audit_logs(actor_user_id,action,resource_type,resource_id,scope_type,correlation_id,outcome,metadata)
  values(p_actor_user_id,'llm.provider.configure','llm_provider',v_provider.id::text,'platform',
    coalesce(nullif(p_correlation_id,''),gen_random_uuid()::text),'success',
    jsonb_build_object('provider_key',v_provider.key,'base_url',rtrim(p_base_url,'/'),'secret_env_name',p_secret_env_name));
  return jsonb_build_object('id',v_provider.id,'key',v_provider.key,'configured',true,'enabled',v_provider.enabled);
end; $function$

