CREATE OR REPLACE FUNCTION public.moreai_review_skill_package(p_skill_id uuid, p_actor_user_id uuid, p_license_status text, p_publication_status text, p_review_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_package public.moreai_skill_packages%rowtype;
  v_report jsonb;
  v_inventory jsonb;
  v_registry jsonb;
  v_findings jsonb;
begin
  if p_skill_id is null or p_actor_user_id is null
     or p_license_status not in ('approved','rejected')
     or p_publication_status not in ('private','published','deprecated')
     or length(btrim(coalesce(p_review_note,''))) < 3 then
    raise exception 'skill_package_review_payload_invalid' using errcode='22023';
  end if;

  select * into v_package
  from public.moreai_skill_packages
  where id=p_skill_id
  for update;

  if not found then
    raise exception 'skill_not_found' using errcode='P0002';
  end if;

  v_report := coalesce(v_package.validation_report,'{}'::jsonb);
  v_inventory := coalesce(v_report->'source_inventory','{}'::jsonb);
  v_registry := coalesce(v_inventory->'registry_resolution','{}'::jsonb);
  v_findings := coalesce(v_report->'findings','[]'::jsonb);

  if jsonb_typeof(v_findings) <> 'array' then
    raise exception 'skill_validation_findings_must_be_an_array' using errcode='23514';
  end if;
  if jsonb_array_length(v_findings) <> 0 then
    raise exception 'skill_validation_findings_must_be_resolved' using errcode='23514';
  end if;
  if p_license_status='approved' and jsonb_typeof(v_inventory->'license_files') <> 'array' then
    raise exception 'skill_license_file_evidence_missing' using errcode='23514';
  end if;
  if p_license_status='approved' and jsonb_array_length(v_inventory->'license_files') = 0 then
    raise exception 'skill_license_file_evidence_missing' using errcode='23514';
  end if;

  if p_license_status='approved' and (
    coalesce(v_package.license_evidence,'')=''
    or v_package.validation_status<>'validated'
    or coalesce((v_inventory->>'unresolved_dependency_count')::integer, -1) <> 0
    or coalesce((v_inventory->>'unresolved_dependency_edge_count')::integer, -1) <> 0
    or coalesce((v_inventory->>'dependency_graph_complete')::boolean, false) is not true
    or coalesce((v_registry->>'unresolved_count')::integer, -1) <> 0
    or coalesce((v_registry->>'registry_metadata_resolved_count')::integer, -1)
       <> coalesce((v_registry->>'exact_version_count')::integer, -2)
  ) then
    raise exception 'skill_requires_complete_dependency_and_license_evidence' using errcode='23514';
  end if;

  if p_publication_status='published' and (
    p_license_status<>'approved'
    or v_package.manifest='{}'::jsonb
    or v_package.validation_status<>'validated'
    or jsonb_typeof(v_inventory->'sbom') <> 'object'
    or jsonb_typeof(v_inventory->'dependencies') <> 'array'
    or coalesce((v_inventory->>'unresolved_dependency_count')::integer, -1) <> 0
    or coalesce((v_registry->>'unresolved_count')::integer, -1) <> 0
  ) then
    raise exception 'skill_requires_complete_validation_and_approved_license_before_publication' using errcode='23514';
  end if;

  update public.moreai_skill_packages
  set
    license_status=p_license_status,
    publication_status=p_publication_status,
    validation_report=jsonb_set(
      coalesce(validation_report,'{}'::jsonb),
      '{review}',
      jsonb_build_object(
        'reviewer_user_id',p_actor_user_id,
        'review_note',left(p_review_note,2000),
        'reviewed_at',now(),
        'decision',p_license_status,
        'publication_status',p_publication_status
      ),
      true
    ),
    updated_at=now()
  where id=p_skill_id
  returning * into v_package;

  insert into public.moreai_skill_registry_audit(
    skill_package_id,actor_user_id,owner_user_id,event_type,decision,event_detail
  ) values (
    p_skill_id,p_actor_user_id,v_package.owner_user_id,
    case when p_license_status='approved' then 'license_reviewed' else 'publication_reviewed' end,
    p_license_status,
    jsonb_build_object(
      'publication_status',p_publication_status,
      'review_note',left(p_review_note,2000),
      'validation_status',v_package.validation_status,
      'unresolved_dependency_count',v_inventory->>'unresolved_dependency_count',
      'registry_unresolved_count',v_registry->>'unresolved_count'
    )
  );

  return jsonb_build_object(
    'id',v_package.id,
    'license_status',v_package.license_status,
    'publication_status',v_package.publication_status,
    'validation_status',v_package.validation_status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_ack_browser_profile_deleted(p_session_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.moreai_browser_sessions%rowtype;
begin
  if p_session_id is null or p_user_id is null then
    raise exception 'browser_profile_ack_identity_invalid' using errcode='22023';
  end if;

  update public.moreai_browser_sessions
  set profile_deleted_at=now(), profile_retention_claimed_at=null
  where id=p_session_id
    and user_id=p_user_id
    and status in ('closed','expired')
    and profile_deleted_at is null
    and profile_retention_after <= now()
  returning * into v_row;

  if found then
    insert into public.moreai_browser_session_events(
      session_id,user_id,event_type,metadata
    ) values (
      p_session_id,p_user_id,'profile_deleted',
      jsonb_build_object('source','worker','retention_policy_days',30)
    );
    return jsonb_build_object('session_id',p_session_id,'status','profile_deleted');
  end if;

  select * into v_row
  from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id;

  if found and v_row.profile_deleted_at is not null then
    return jsonb_build_object('session_id',p_session_id,'status','profile_deleted','replayed',true);
  end if;

  raise exception 'browser_profile_retention_gate_not_satisfied' using errcode='23514';
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_request_browser_session_close(p_session_id uuid, p_user_id uuid, p_source text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.moreai_browser_sessions%rowtype;
begin
  if p_session_id is null or p_user_id is null
     or p_source not in ('customer','ttl_reconciler','acquire_guard')
     or (p_reason is not null and p_reason not in ('ttl','idle','ttl_or_idle')) then
    raise exception 'browser_session_close_request_invalid' using errcode='22023';
  end if;

  select * into v_row
  from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id
  for update;

  if not found then
    raise exception 'browser_session_not_found' using errcode='P0002';
  end if;

  if v_row.status in ('close_requested','closed') then
    return jsonb_build_object(
      'session_id',p_session_id,'status',v_row.status,'replayed',true
    );
  end if;

  if v_row.status <> 'active' then
    raise exception 'browser_session_not_active' using errcode='P0002';
  end if;

  update public.moreai_browser_sessions
  set status='close_requested'
  where id=p_session_id and user_id=p_user_id;

  insert into public.moreai_browser_session_events(
    session_id,user_id,event_type,metadata
  ) values (
    p_session_id,p_user_id,'close_requested',
    jsonb_strip_nulls(jsonb_build_object('source',p_source,'reason',p_reason))
  );

  return jsonb_build_object('session_id',p_session_id,'status','close_requested');
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_customer_clear_memory_atomic(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_preferences_updated bigint := 0;
  v_memories_deleted bigint := 0;
  v_episodes_cleared bigint := 0;
begin
  if p_user_id is null then
    raise exception 'memory_clear_user_required' using errcode = '22023';
  end if;

  -- Serialize against the create RPC below. If a create already owns this row,
  -- it commits before this clear; otherwise later creates see disabled consent.
  perform 1
    from public.moreai_customer_memory_preferences
   where user_id = p_user_id
   for update;

  update public.moreai_customer_memory_preferences
     set enabled = false,
         disabled_at = now(),
         updated_at = now()
   where user_id = p_user_id;
  get diagnostics v_preferences_updated = row_count;

  delete from public.moreai_customer_memories
   where user_id = p_user_id;
  get diagnostics v_memories_deleted = row_count;

  -- Match the existing API cleanup semantics: remove only episodic-memory
  -- metadata, retaining the original conversation message and all citations.
  update public.conversation_messages
     set metadata = metadata - array[
       'memory_type',
       'memory_scope',
       'workspace_id',
       'episode',
       'episode_expires_at'
     ]::text[]
   where user_id = p_user_id
     and metadata ->> 'memory_type' = 'episodic';
  get diagnostics v_episodes_cleared = row_count;

  return jsonb_build_object(
    'completed', true,
    'consent_disabled', v_preferences_updated > 0,
    'memories_deleted', v_memories_deleted,
    'episodes_cleared', v_episodes_cleared
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_customer_disable_memory_consent_atomic(p_user_id uuid, p_consent_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_preference public.moreai_customer_memory_preferences%rowtype;
  v_episodes_cleared bigint := 0;
begin
  if p_user_id is null
     or p_consent_version is null
     or length(p_consent_version) not between 1 and 40 then
    raise exception 'memory_consent_arguments_invalid' using errcode = '22023';
  end if;

  insert into public.moreai_customer_memory_preferences (
    user_id, enabled, consent_version, disabled_at, updated_at
  ) values (
    p_user_id, false, p_consent_version, now(), now()
  )
  on conflict (user_id) do update set
    enabled = false,
    consent_version = excluded.consent_version,
    disabled_at = now(),
    updated_at = now()
  returning * into v_preference;

  update public.conversation_messages
     set metadata = metadata - array[
       'memory_type',
       'memory_scope',
       'workspace_id',
       'episode',
       'episode_expires_at'
     ]::text[]
   where user_id = p_user_id
     and metadata ->> 'memory_type' = 'episodic';
  get diagnostics v_episodes_cleared = row_count;

  return jsonb_build_object(
    'enabled', v_preference.enabled,
    'consent_version', v_preference.consent_version,
    'consented_at', v_preference.consented_at,
    'disabled_at', v_preference.disabled_at,
    'updated_at', v_preference.updated_at,
    'episodes_cleared', v_episodes_cleared
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_complete_browser_session_close(p_session_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.moreai_browser_sessions%rowtype;
begin
  if p_session_id is null or p_user_id is null then
    raise exception 'browser_session_close_identity_invalid' using errcode='22023';
  end if;
  select * into v_row from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id for update;
  if not found then
    raise exception 'browser_session_close_request_not_found' using errcode='P0002';
  end if;
  if v_row.status='closed' then
    delete from public.moreai_browser_capacity_leases where session_id=p_session_id and user_id=p_user_id;
    return jsonb_build_object('session_id',p_session_id,'status','closed','replayed',true);
  end if;
  if v_row.status<>'close_requested' then
    raise exception 'browser_session_close_request_not_found' using errcode='P0002';
  end if;
  update public.moreai_browser_sessions
  set status='closed',encrypted_state=null,closed_at=now(),
      profile_retention_after=now()+interval '30 days'
  where id=p_session_id and user_id=p_user_id;
  delete from public.moreai_browser_capacity_leases where session_id=p_session_id and user_id=p_user_id;
  insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
  values(p_session_id,p_user_id,'closed',jsonb_build_object('source','worker_reconciler'));
  return jsonb_build_object('session_id',p_session_id,'status','closed');
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_mark_browser_session_closed(p_session_id uuid, p_user_id uuid, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.moreai_browser_sessions%rowtype;
begin
  if p_session_id is null or p_user_id is null or p_run_id is null then
    raise exception 'browser_session_close_identity_invalid' using errcode='22023';
  end if;
  select * into v_row from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id for update;
  if not found then
    raise exception 'browser_session_not_found' using errcode='P0002';
  end if;
  if v_row.status='closed' then
    delete from public.moreai_browser_capacity_leases where session_id=p_session_id and user_id=p_user_id;
    return jsonb_build_object('session_id',p_session_id,'status','closed','replayed',true);
  end if;
  if v_row.status not in ('active','close_requested') then
    raise exception 'browser_session_not_active' using errcode='P0002';
  end if;
  update public.moreai_browser_sessions
  set status='closed',encrypted_state=null,closed_at=now(),
      profile_retention_after=now()+interval '30 days'
  where id=p_session_id and user_id=p_user_id;
  delete from public.moreai_browser_capacity_leases where session_id=p_session_id and user_id=p_user_id;
  insert into public.moreai_browser_session_events(session_id,user_id,event_type,metadata)
  values(p_session_id,p_user_id,'closed',
    jsonb_build_object('source','worker','run_id',p_run_id));
  return jsonb_build_object('session_id',p_session_id,'status','closed');
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_acquire_browser_capacity_lease(p_session_id uuid, p_user_id uuid, p_worker_id text, p_lease_seconds integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_session public.moreai_browser_sessions%rowtype;
  v_lease public.moreai_browser_capacity_leases%rowtype;
  v_global_count integer;
  v_user_count integer;
  v_token uuid;
  v_expiry timestamptz;
begin
  if p_session_id is null or p_user_id is null
     or p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9._:-]{1,128}$'
     or p_lease_seconds is null or p_lease_seconds not between 60 and 900 then
    raise exception 'browser_capacity_lease_arguments_invalid' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('moreai_browser_capacity_global', 0));

  select * into v_session
  from public.moreai_browser_sessions
  where id=p_session_id and user_id=p_user_id and status='active'
  for update;

  if not found then
    return jsonb_build_object('acquired',false,'reason','session_not_active');
  end if;

  select * into v_lease
  from public.moreai_browser_capacity_leases
  where session_id=p_session_id
  for update;

  if found and v_lease.user_id=p_user_id and v_lease.expires_at>now() then
    if v_lease.worker_id<>p_worker_id then
      return jsonb_build_object(
        'acquired',false,
        'reason','session_lease_owned_by_other_worker',
        'expires_at',v_lease.expires_at
      );
    end if;
    update public.moreai_browser_capacity_leases
    set expires_at=now()+(p_lease_seconds * interval '1 second'), updated_at=now()
    where session_id=p_session_id
    returning lease_token, expires_at into v_token, v_expiry;
    return jsonb_build_object('acquired',true,'lease_token',v_token,'expires_at',v_expiry,'reused',true);
  end if;

  delete from public.moreai_browser_capacity_leases
  where expires_at<=now();

  select count(*)::integer into v_global_count
  from public.moreai_browser_capacity_leases
  where expires_at>now();

  select count(*)::integer into v_user_count
  from public.moreai_browser_capacity_leases
  where user_id=p_user_id and expires_at>now();

  if v_global_count>=3 then
    return jsonb_build_object('acquired',false,'reason','global_capacity_limit','limit',3);
  end if;
  if v_user_count>=2 then
    return jsonb_build_object('acquired',false,'reason','tenant_capacity_limit','limit',2);
  end if;

  insert into public.moreai_browser_capacity_leases(
    session_id,user_id,worker_id,lease_token,expires_at
  ) values (
    p_session_id,p_user_id,p_worker_id,gen_random_uuid(),now()+(p_lease_seconds * interval '1 second')
  )
  on conflict(session_id) do update set
    user_id=excluded.user_id,
    worker_id=excluded.worker_id,
    lease_token=excluded.lease_token,
    expires_at=excluded.expires_at,
    updated_at=now()
  returning lease_token,expires_at into v_token,v_expiry;

  return jsonb_build_object('acquired',true,'lease_token',v_token,'expires_at',v_expiry,'reused',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.moreai_ingest_skill_source(p_skill_id uuid, p_owner_user_id uuid, p_files jsonb, p_validation_report jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_package public.moreai_skill_packages%rowtype;
  v_count integer;
  v_bytes bigint;
begin
  if p_skill_id is null or p_owner_user_id is null
     or jsonb_typeof(p_files)<>'array' or jsonb_array_length(p_files)<1
     or jsonb_array_length(p_files)>64 or jsonb_typeof(p_validation_report)<>'object' then
    raise exception 'skill_source_ingestion_payload_invalid' using errcode='22023';
  end if;
  select * into v_package from public.moreai_skill_packages
   where id=p_skill_id and owner_user_id=p_owner_user_id for update;
  if not found then raise exception 'skill_not_found' using errcode='42501'; end if;
  if exists(select 1 from public.moreai_skill_source_files where skill_package_id=p_skill_id) then
    raise exception 'skill_source_already_ingested_immutable' using errcode='23505';
  end if;
  select count(*),coalesce(sum((x->>'byte_size')::bigint),0)
    into v_count,v_bytes from jsonb_array_elements(p_files) x;
  if v_count<>jsonb_array_length(p_files) or v_bytes>5242880 then
    raise exception 'skill_source_package_size_limit_exceeded' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_array_elements(p_files) x
    where coalesce(x->>'relative_path','')='' or x->>'relative_path' ~ '(^/|(^|/)\.\.(/|$))'
       or coalesce(x->>'git_blob_sha','') !~ '^[0-9a-f]{40}$'
       or coalesce(x->>'content_sha256','') !~ '^[0-9a-f]{64}$'
       or coalesce((x->>'byte_size')::integer,-1)<0
       or (x->>'byte_size')::integer>524288
       or ((x->>'text_content') is null) = ((x->>'binary_content_base64') is null)
  ) then raise exception 'skill_source_file_record_invalid' using errcode='22023'; end if;
  if (select count(distinct x->>'relative_path') from jsonb_array_elements(p_files) x)<>v_count then
    raise exception 'skill_source_duplicate_path' using errcode='22023'; end if;
  insert into public.moreai_skill_source_files(
    skill_package_id,owner_user_id,relative_path,git_blob_sha,content_sha256,
    media_type,byte_size,text_content,binary_content_base64
  )
  select p_skill_id,p_owner_user_id,x->>'relative_path',x->>'git_blob_sha',x->>'content_sha256',
    x->>'media_type',(x->>'byte_size')::integer,x->>'text_content',x->>'binary_content_base64'
  from jsonb_array_elements(p_files) x;
  update public.moreai_skill_packages set
    validation_status='pending',validation_report=p_validation_report,updated_at=now()
  where id=p_skill_id and owner_user_id=p_owner_user_id;
  insert into public.moreai_skill_registry_audit(
    skill_package_id,owner_user_id,event_type,event_detail
  ) values(
    p_skill_id,p_owner_user_id,'source_ingested',
    jsonb_build_object('file_count',v_count,'total_bytes',v_bytes,'source_commit',v_package.source_commit)
  );
  return jsonb_build_object('skill_id',p_skill_id,'file_count',v_count,'total_bytes',v_bytes,'integrity','verified');
end;
$function$
